    public bool Execute()
    {
        return ShowPagePicker();
    }

    // -------------------------------------------------------------------------
    // PUBLIC METHODS FOR "EXECUTE C# METHOD"
    // -------------------------------------------------------------------------

    public bool SetupBridge()
    {
        return RunSta(delegate { return ShowSetupWindow(); });
    }

    public bool SwitchPage()
    {
        try
        {
            BridgeState state = LoadState();
            List<BridgeProfileState> configured = GetSwitchableProfiles(state);

            string requestedProfile = GetStringArg(ArgProfile);
            if (string.IsNullOrWhiteSpace(requestedProfile))
                requestedProfile = GetStringArg("profile");

            object pageArg = GetPageArgument();

            if (configured.Count == 0)
            {
                CPH.LogWarn("[SD Bridge] No Bridge profile is configured. Run SetupBridge first.");
                return false;
            }

            BridgeProfileState target = ResolveConfiguredProfile(configured, requestedProfile);
            if (target == null)
            {
                if (string.IsNullOrWhiteSpace(requestedProfile) && configured.Count > 1)
                    return ShowPagePicker();

                CPH.LogWarn("[SD Bridge] Unknown Bridge profile: " + (requestedProfile ?? "<empty>"));
                return false;
            }

            ProfileInfo liveProfile = FindLiveBridgeProfile(target);
            if (liveProfile == null)
            {
                CPH.LogWarn("[SD Bridge] The bridged Stream Deck profile '" + target.BridgeName +
                    "' is not installed yet. Install/update the generated plugin and accept the profile import.");
                return false;
            }

            int pageNumber;
            string pageLabel;
            if (!ResolvePage(liveProfile, pageArg, out pageNumber, out pageLabel))
            {
                if (pageArg == null)
                    return ShowPagePicker();

                CPH.LogWarn("[SD Bridge] Invalid page for '" + liveProfile.Name + "'. Available pages: " +
                    string.Join(" | ", liveProfile.Pages.Select((p, i) => (i + 1).ToString(CultureInfo.InvariantCulture) + ":" + p)));
                return false;
            }

            return QueueSwitch(target, pageNumber, pageLabel, liveProfile.Pages.Count);
        }
        catch (Exception ex)
        {
            CPH.LogError("[SD Bridge] SwitchPage failed: " + ex);
            return false;
        }
    }

    public bool ShowPagePicker()
    {
        return RunSta(delegate { return ShowPagePickerWindow(); });
    }

    public bool RefreshProfiles()
    {
        try
        {
            List<ProfileInfo> profiles = ScanProfiles();
            CPH.SetArgument("sdBridge.profileCount", profiles.Count);
            CPH.SetArgument("sdBridge.profiles", string.Join(" | ", profiles.Select(p => p.Name)));

            foreach (ProfileInfo p in profiles)
            {
                CPH.LogInfo("[SD Bridge] Profile: " + p.Name + " | " + p.Pages.Count + " page(s) | " +
                    DeviceTypeName(p.DeviceType) + " | " + p.StoreVersion);
            }
            return true;
        }
        catch (Exception ex)
        {
            CPH.LogError("[SD Bridge] RefreshProfiles failed: " + ex);
            return false;
        }
    }

    public bool ListPages()
    {
        try
        {
            string requestedProfile = GetStringArg(ArgProfile);
            if (string.IsNullOrWhiteSpace(requestedProfile))
                requestedProfile = GetStringArg("profile");

            BridgeState state = LoadState();
            BridgeProfileState target = ResolveConfiguredProfile(GetSwitchableProfiles(state), requestedProfile);
            if (target == null)
            {
                CPH.LogWarn("[SD Bridge] ListPages: unknown profile '" + (requestedProfile ?? "<empty>") + "'.");
                return false;
            }

            ProfileInfo live = FindLiveBridgeProfile(target);
            if (live == null)
            {
                CPH.LogWarn("[SD Bridge] ListPages: bridged profile is not installed: " + target.BridgeName);
                return false;
            }

            CPH.SetArgument("sdBridge.pageCount", live.Pages.Count);
            CPH.SetArgument("sdBridge.pages", string.Join(" | ", live.Pages.Select((p, i) =>
                (i + 1).ToString(CultureInfo.InvariantCulture) + ":" + p)));

            CPH.LogInfo("[SD Bridge] " + live.Name + " => " + live.Pages.Count + " page(s): " +
                string.Join(" | ", live.Pages.Select((p, i) => (i + 1).ToString(CultureInfo.InvariantCulture) + ":" + p)));
            return true;
        }
        catch (Exception ex)
        {
            CPH.LogError("[SD Bridge] ListPages failed: " + ex);
            return false;
        }
    }

    // -------------------------------------------------------------------------
    // SETUP / CONVERSION WPF
    // -------------------------------------------------------------------------

    private bool ShowSetupWindow()
    {
        List<ProfileInfo> allDetected = ScanProfiles()
            .OrderBy(p => p.Name, StringComparer.OrdinalIgnoreCase)
            .ToList();

        BridgeState currentState = LoadState();

        // V14: treat the temporary validation profile as a real lifecycle state.
        // If it is still physically present, do not propose it as a new/recommended install.
        ProfileInfo liveValidationProfile = allDetected.FirstOrDefault(p =>
            p.DeviceType == ValidationDeviceType &&
            string.Equals(p.Name, ValidationProfileDisplayName, StringComparison.OrdinalIgnoreCase));
        bool validationAlreadyInstalled = liveValidationProfile != null;

        // If validation was previously confirmed and the temporary profile is now gone,
        // reconcile the persistent state silently. There is no reason to force a plugin rebuild
        // only to remove a disposable validation profile from the remembered state.
        if (currentState.ValidationPassed && !validationAlreadyInstalled && currentState.IncludesValidationProfile)
        {
            currentState.IncludesValidationProfile = false;
            currentState.Profiles = (currentState.Profiles ?? new List<BridgeProfileState>())
                .Where(p => !p.IsValidationTest)
                .ToList();
            SaveState(currentState);
        }

        List<BridgeProfileState> configuredStates = GetConfiguredProfiles(currentState);
        PersistReconciledState(currentState, configuredStates);

        List<Tuple<BridgeProfileState, ProfileInfo>> liveBridgePairs =
            new List<Tuple<BridgeProfileState, ProfileInfo>>();

        foreach (BridgeProfileState state in configuredStates)
        {
            ProfileInfo live = FindLiveProfileForState(state, allDetected);
            if (live != null)
                liveBridgePairs.Add(Tuple.Create(state, live));
        }

        List<BridgeProfileState> existingBridgeStates = liveBridgePairs
            .Select(x => x.Item1)
            .ToList();

        HashSet<string> alreadyBridged = new HashSet<string>(
            existingBridgeStates.Select(p => ProfileIdentityKey(p.SourceName, p.DeviceType)),
            StringComparer.OrdinalIgnoreCase);

        List<ProfileInfo> availableProfiles = allDetected
            .Where(p => !p.IsManagedBridge)
            .Where(p => !p.Name.EndsWith(BridgeSuffix, StringComparison.OrdinalIgnoreCase))
            .Where(p => !string.Equals(p.Name, ValidationProfileName, StringComparison.OrdinalIgnoreCase))
            .Where(p => !string.Equals(p.Name, ValidationProfileDisplayName, StringComparison.OrdinalIgnoreCase))
            .Where(p => !alreadyBridged.Contains(ProfileIdentityKey(p.Name, p.DeviceType)))
            .ToList();

        Window window = CreateWindow("SD Bridge", 920, 700);
        EnableWindowPlacement(window, "setup");

        Grid root = new Grid { Margin = new Thickness(14) };
        root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        SetWindowContent(window, root);

        // HEADER — intentionally aligned with the other Streamer.bot WPF tools.
        Grid header = new Grid { Margin = new Thickness(2, 2, 2, 14) };
        header.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        header.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        StackPanel titleBlock = new StackPanel();
        titleBlock.Children.Add(new TextBlock
        {
            Text = "SD Bridge",
            FontSize = 18,
            FontWeight = FontWeights.SemiBold,
            Foreground = Brushes.White
        });
        titleBlock.Children.Add(new TextBlock
        {
            Text = "Direct Stream Deck profile and page switching from Streamer.bot",
            FontSize = 11.5,
            Foreground = ThemeMuted(),
            Margin = new Thickness(0, 3, 0, 0)
        });
        Grid.SetColumn(titleBlock, 0);
        header.Children.Add(titleBlock);

        StackPanel headerActions = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            VerticalAlignment = VerticalAlignment.Center
        };
        Button rebuildStateTop = MakeButton("Clean / Rebuild state", 168, "secondary");
        Button refreshTop = MakeButton("↻  Refresh", 112, "secondary");
        Button closeTop = MakeButton("Close", 88, "secondary");
        headerActions.Children.Add(rebuildStateTop);
        headerActions.Children.Add(refreshTop);
        headerActions.Children.Add(closeTop);
        Grid.SetColumn(headerActions, 1);
        header.Children.Add(headerActions);

        Grid.SetRow(header, 0);
        root.Children.Add(header);

        ScrollViewer scroll = new ScrollViewer
        {
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
        };
        StackPanel content = new StackPanel();
        scroll.Content = content;
        Grid.SetRow(scroll, 1);
        root.Children.Add(scroll);

        // Compact status / workflow line.
        Border workflow = MakePanel(new Thickness(0, 0, 0, 12));
        Grid workflowGrid = new Grid();
        workflowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        workflowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        workflowGrid.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        TextBlock workflowLabel = new TextBlock
        {
            Text = "Setup",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(workflowLabel, 0);
        workflowGrid.Children.Add(workflowLabel);

        TextBlock workflowText = new TextBlock
        {
            Text = "Select the profiles you want to control. Already bridged profiles are preserved automatically.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(14, 0, 14, 0),
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(workflowText, 1);
        workflowGrid.Children.Add(workflowText);

        TextBlock xlStatus = new TextBlock
        {
            Text = "●   •  Multi-device",
            Foreground = ThemeAccent(),
            FontSize = 11.5,
            FontWeight = FontWeights.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(xlStatus, 2);
        workflowGrid.Children.Add(xlStatus);
        workflow.Child = workflowGrid;
        content.Children.Add(workflow);

        // PROFILES PANEL
        Border profilesPanel = MakePanel(new Thickness(0, 0, 0, 12));
        StackPanel profilesStack = new StackPanel();
        profilesPanel.Child = profilesStack;

        Grid profilesHeader = new Grid { Margin = new Thickness(0, 0, 0, 10) };
        profilesHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        profilesHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        StackPanel profileHeaderText = new StackPanel();
        profileHeaderText.Children.Add(new TextBlock
        {
            Text = "Stream Deck profiles",
            FontWeight = FontWeights.SemiBold,
            Foreground = Brushes.White,
            FontSize = 14
        });
        profileHeaderText.Children.Add(new TextBlock
        {
            Text = "Only [Bridge] versions can use direct profile and page switching.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            Margin = new Thickness(0, 3, 0, 0)
        });
        profileHeaderText.Children.Add(new TextBlock
        {
            Text = "Streamer.bot arguments: sdBridge.profile = bridged profile name  •  sdBridge.page = page name OR 1-based page number.",
            Foreground = ThemeMuted2(),
            FontSize = 10.8,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 3, 0, 0)
        });
        Grid.SetColumn(profileHeaderText, 0);
        profilesHeader.Children.Add(profileHeaderText);

        TextBlock countText = new TextBlock
        {
            Text = allDetected.Count.ToString(CultureInfo.InvariantCulture) + " detected",
            Foreground = ThemeMuted2(),
            FontSize = 11.5,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(countText, 1);
        profilesHeader.Children.Add(countText);
        profilesStack.Children.Add(profilesHeader);

        List<Tuple<CheckBox, ProfileInfo>> checks = new List<Tuple<CheckBox, ProfileInfo>>();

        if (liveBridgePairs.Count > 0)
        {
            profilesStack.Children.Add(MakeSectionLabel("ALREADY BRIDGED"));

            foreach (Tuple<BridgeProfileState, ProfileInfo> pair in liveBridgePairs)
            {
                ProfileInfo live = pair.Item2;

                Grid row = new Grid { Margin = new Thickness(0, 4, 0, 4) };
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
                row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

                TextBlock mark = new TextBlock
                {
                    Text = "✓",
                    Foreground = ThemeAccent(),
                    FontWeight = FontWeights.Bold,
                    Width = 24,
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(2, 2, 8, 0)
                };
                Grid.SetColumn(mark, 0);
                row.Children.Add(mark);

                StackPanel info = new StackPanel();
                info.Children.Add(new TextBlock
                {
                    Text = live.Name,
                    Foreground = Brushes.White,
                    FontWeight = FontWeights.SemiBold
                });
                info.Children.Add(new TextBlock
                {
                    Text = live.Pages.Count.ToString(CultureInfo.InvariantCulture) +
                           " page(s)  •  " + DeviceTypeName(live.DeviceType) + "  •  " + live.StoreVersion +
                           "  •  " + FormatPagesPreview(live.Pages),
                    Foreground = ThemeMuted(),
                    FontSize = 11.5,
                    TextWrapping = TextWrapping.Wrap,
                    Margin = new Thickness(0, 3, 0, 0)
                });
                Grid.SetColumn(info, 1);
                row.Children.Add(info);

                string bridgeNameToCopy = live.Name;
                Button copyProfileName = MakeButton("Copy name", 94, "secondary");
                copyProfileName.Height = 28;
                copyProfileName.Margin = new Thickness(10, 0, 0, 0);
                copyProfileName.VerticalAlignment = VerticalAlignment.Top;
                copyProfileName.ToolTip = "Copy the current bridged profile name for the Streamer.bot argument sdBridge.profile.";
                copyProfileName.Click += delegate
                {
                    try
                    {
                        Clipboard.SetText(bridgeNameToCopy);
                        copyProfileName.Content = "Copied ✓";
                        CPH.LogInfo("[SD Bridge] Copied Bridge profile name: " + bridgeNameToCopy);
                    }
                    catch (Exception ex)
                    {
                        CPH.LogWarn("[SD Bridge] Could not copy Bridge profile name: " + ex.Message);
                        MessageBox.Show(window,
                            "Could not copy the profile name to the clipboard.\n\n" + ex.Message,
                            PluginName, MessageBoxButton.OK, MessageBoxImage.Warning);
                    }
                };
                Grid.SetColumn(copyProfileName, 2);
                row.Children.Add(copyProfileName);

                TextBlock status = new TextBlock
                {
                    Text = "Bridged",
                    Foreground = ThemeAccent(),
                    FontSize = 11.5,
                    FontWeight = FontWeights.SemiBold,
                    VerticalAlignment = VerticalAlignment.Top,
                    Margin = new Thickness(12, 5, 2, 0)
                };
                Grid.SetColumn(status, 3);
                row.Children.Add(status);

                profilesStack.Children.Add(MakeListRow(row));
            }

            profilesStack.Children.Add(new Border
            {
                Height = 1,
                Background = ThemeBorder(),
                Margin = new Thickness(0, 10, 0, 10)
            });
        }

        profilesStack.Children.Add(MakeSectionLabel("AVAILABLE TO BRIDGE"));

        foreach (ProfileInfo p in availableProfiles)
        {
            bool supported = IsBridgeableDeviceType(p.DeviceType);

            Grid row = new Grid { Margin = new Thickness(0, 4, 0, 4) };
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            CheckBox cb = new CheckBox
            {
                IsChecked = supported,
                IsEnabled = supported,
                VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(2, 2, 10, 0),
                ToolTip = supported ? null : "Unknown or unsupported Stream Deck DeviceType."
            };
            Grid.SetColumn(cb, 0);
            row.Children.Add(cb);

            StackPanel info = new StackPanel();
            info.Children.Add(new TextBlock
            {
                Text = p.Name,
                Foreground = supported ? Brushes.White : ThemeMuted2(),
                FontWeight = FontWeights.SemiBold
            });
            info.Children.Add(new TextBlock
            {
                Text = p.Pages.Count.ToString(CultureInfo.InvariantCulture) + " page(s)  •  " +
                       DeviceTypeName(p.DeviceType) + "  •  " + p.StoreVersion,
                Foreground = ThemeMuted(),
                FontSize = 11.5,
                Margin = new Thickness(0, 3, 0, 0)
            });
            info.Children.Add(new TextBlock
            {
                Text = supported ? FormatPagesPreview(p.Pages) : "Unknown or unsupported DeviceType.",
                Foreground = supported ? ThemeMuted2() : ThemeWarning(),
                FontSize = 11,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 3, 0, 0)
            });
            Grid.SetColumn(info, 1);
            row.Children.Add(info);

            TextBlock state = new TextBlock
            {
                Text = supported ? "Ready" : "Unsupported",
                Foreground = supported ? ThemeAccent() : ThemeWarning(),
                FontSize = 11.5,
                VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(12, 2, 2, 0)
            };
            Grid.SetColumn(state, 2);
            row.Children.Add(state);

            profilesStack.Children.Add(MakeListRow(row));
            checks.Add(Tuple.Create(cb, p));
        }

        if (availableProfiles.Count == 0)
        {
            TextBlock none = new TextBlock
            {
                Text = existingBridgeStates.Count > 0
                    ? "No new compatible profile is available to bridge."
                    : "No compatible Stream Deck profile was detected.",
                Foreground = ThemeMuted(),
                Margin = new Thickness(4, 8, 4, 6)
            };
            profilesStack.Children.Add(none);
        }

        content.Children.Add(profilesPanel);

        // VALIDATION PANEL
        Border validationPanel = MakePanel(new Thickness(0, 0, 0, 12));
        StackPanel validationStack = new StackPanel();
        validationPanel.Child = validationStack;

        validationStack.Children.Add(new TextBlock
        {
            Text = "Automatic validation",
            FontWeight = FontWeights.SemiBold,
            Foreground = Brushes.White,
            FontSize = 14
        });
        validationStack.Children.Add(new TextBlock
        {
            Text = "The temporary test profile visually verifies both profile switching and page switching.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 3, 0, 10)
        });

        Grid validationRow = new Grid();
        validationRow.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        validationRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        validationRow.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        bool hasAnyXlProfile =
            existingBridgeStates.Any(p => p.DeviceType == ValidationDeviceType) ||
            availableProfiles.Any(p => p.DeviceType == ValidationDeviceType);

        bool validationWasPreviouslyPassed = currentState.ValidationPassed;
        bool noLiveBridgeInstalled = existingBridgeStates.Count == 0;
        bool validationShouldBeSuggested = hasAnyXlProfile && !validationAlreadyInstalled &&
            (noLiveBridgeInstalled || !validationWasPreviouslyPassed);

        CheckBox includeValidation = new CheckBox
        {
            // Installed => preserved automatically, not proposed as something to add again.
            // Already validated and removed => stays optional/unselected on later runs.
            IsChecked = validationAlreadyInstalled || validationShouldBeSuggested,
            IsEnabled = hasAnyXlProfile && !validationAlreadyInstalled,
            VerticalAlignment = VerticalAlignment.Top,
            Margin = new Thickness(2, 2, 10, 0),
            ToolTip = validationAlreadyInstalled
                ? "The temporary validation profile is already installed and will be preserved if a rebuild is required."
                : (hasAnyXlProfile
                    ? (noLiveBridgeInstalled
                        ? "No live [Bridge] profile is currently detected, so the temporary validation profile is selected by default."
                        : (validationWasPreviouslyPassed
                            ? "Validation was already confirmed previously. Reinstalling the temporary test is optional."
                            : "The embedded validation profile targets Stream Deck XL."))
                    : "The embedded validation profile is XL-only and no XL profile is part of this setup.")
        };
        Grid.SetColumn(includeValidation, 0);
        validationRow.Children.Add(includeValidation);

        StackPanel validationInfo = new StackPanel();
        validationInfo.Children.Add(new TextBlock
        {
            Text = "Bridge Validation Test",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold
        });
        validationInfo.Children.Add(new TextBlock
        {
            Text = validationAlreadyInstalled
                ? "10 pages • Stream Deck XL • already installed • preserved automatically"
                : (validationShouldBeSuggested
                    ? "10 pages • Stream Deck XL • selected by default for first/fresh Bridge validation"
                    : (validationWasPreviouslyPassed
                        ? "10 pages • Stream Deck XL • validation already confirmed previously • optional"
                        : "10 pages • Stream Deck XL • embedded in the Core • can be removed automatically after validation")),
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            Margin = new Thickness(0, 3, 0, 0)
        });
        Grid.SetColumn(validationInfo, 1);
        validationRow.Children.Add(validationInfo);

        TextBlock recommended = new TextBlock
        {
            Text = validationAlreadyInstalled
                ? "Installed"
                : (validationShouldBeSuggested
                    ? "Recommended"
                    : (validationWasPreviouslyPassed
                        ? "Optional"
                        : (hasAnyXlProfile ? "Recommended" : "XL only"))),
            Foreground = (validationAlreadyInstalled || validationShouldBeSuggested)
                ? ThemeAccent()
                : ThemeMuted2(),
            FontSize = 11.5,
            FontWeight = FontWeights.SemiBold,
            VerticalAlignment = VerticalAlignment.Top,
            Margin = new Thickness(12, 2, 2, 0)
        };
        Grid.SetColumn(recommended, 2);
        validationRow.Children.Add(recommended);

        validationStack.Children.Add(MakeListRow(validationRow));
        content.Children.Add(validationPanel);

        // FOOTER
        Grid footer = new Grid { Margin = new Thickness(2, 12, 2, 0) };
        footer.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        footer.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        TextBlock footerHint = new TextBlock
        {
            Text = "The live Bridge profile is the source of truth: edits/pages are preserved, and reruns update the same Bridge instead of creating [Bridge] [Bridge].",
            Foreground = ThemeMuted2(),
            FontSize = 11,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(footerHint, 0);
        footer.Children.Add(footerHint);

        Button generate = MakeButton(
            existingBridgeStates.Count > 0 ? "Update plugin" : "Generate plugin",
            168,
            "primary");

        bool hasMissingConfiguredBridge = configuredStates.Any(p => FindLiveProfileForState(p, allDetected) == null);

        Action refreshGenerateState = delegate
        {
            bool hasSelectedNewProfile = checks.Any(x => x.Item1.IsChecked == true);
            bool wantsValidationProfile = includeValidation.IsChecked == true && hasAnyXlProfile;
            // Physical presence is authoritative here: stale state.json must not prevent
            // the temporary test profile from being regenerated when it is requested but absent.
            bool validationChange =
                (!validationAlreadyInstalled && wantsValidationProfile) ||
                (validationAlreadyInstalled && !currentState.IncludesValidationProfile);

            bool needsUpdate =
                existingBridgeStates.Count == 0 ||
                hasSelectedNewProfile ||
                hasMissingConfiguredBridge ||
                validationChange;

            generate.IsEnabled = needsUpdate;
            generate.Content = needsUpdate
                ? (existingBridgeStates.Count > 0 ? "Update plugin" : "Generate plugin")
                : "Plugin up to date";
        };

        foreach (Tuple<CheckBox, ProfileInfo> item in checks)
            item.Item1.Checked += delegate { refreshGenerateState(); };
        foreach (Tuple<CheckBox, ProfileInfo> item in checks)
            item.Item1.Unchecked += delegate { refreshGenerateState(); };
        includeValidation.Checked += delegate { refreshGenerateState(); };
        includeValidation.Unchecked += delegate { refreshGenerateState(); };

        refreshGenerateState();

        Grid.SetColumn(generate, 1);
        footer.Children.Add(generate);

        Grid.SetRow(footer, 2);
        root.Children.Add(footer);

        rebuildStateTop.Click += delegate
        {
            bool answer = ShowEnglishConfirm(
                window,
                "Clean / Rebuild state",
                "This will rebuild state.json from the Bridge profiles currently present in Stream Deck " +
                "and the bridge-config.json of the installed addon.\n\n" +
                "A safety copy of the current state.json will be created first. Orphaned/duplicate entries " +
                "will be removed and aliases will be compacted.\n\n" +
                "Continue?",
                "Rebuild state",
                "Cancel");

            if (!answer)
                return;

            try
            {
                StateRebuildResult result = CleanAndRebuildState();
                string message =
                    "state.json rebuilt successfully.\n\n" +
                    "Live Bridge profiles: " + result.LiveBridgeCount.ToString(CultureInfo.InvariantCulture) + "\n" +
                    "State entries: " + result.EntryCount.ToString(CultureInfo.InvariantCulture) + "\n" +
                    "Removed orphan/duplicate entries: " + result.RemovedEntryCount.ToString(CultureInfo.InvariantCulture) + "\n" +
                    "Aliases before/after: " + result.AliasesBefore.ToString(CultureInfo.InvariantCulture) +
                    " / " + result.AliasesAfter.ToString(CultureInfo.InvariantCulture);

                if (!string.IsNullOrWhiteSpace(result.BackupPath))
                    message += "\n\nSafety backup:\n" + result.BackupPath;

                if (result.Warnings.Count > 0)
                    message += "\n\nWarnings:\n• " + string.Join("\n• ", result.Warnings);

                MessageBox.Show(window, message, PluginName, MessageBoxButton.OK,
                    result.Warnings.Count > 0 ? MessageBoxImage.Warning : MessageBoxImage.Information);

                window.Close();
                ThreadPool.QueueUserWorkItem(delegate { SetupBridge(); });
            }
            catch (Exception ex)
            {
                CPH.LogError("[SD Bridge] Clean / Rebuild state failed: " + ex);
                MessageBox.Show(window,
                    "state.json rebuild failed. The existing state was left untouched when possible.\n\n" + ex.Message,
                    PluginName, MessageBoxButton.OK, MessageBoxImage.Error);
            }
        };

        refreshTop.Click += delegate
        {
            window.Close();
            ThreadPool.QueueUserWorkItem(delegate { SetupBridge(); });
        };

        closeTop.Click += delegate { window.Close(); };

        generate.Click += delegate
        {
            List<ProfileInfo> selected = checks
                .Where(x => x.Item1.IsChecked == true)
                .Select(x => x.Item2)
                .ToList();

            if (selected.Count == 0 && existingBridgeStates.Count == 0)
            {
                MessageBox.Show(window,
                    "Select at least one compatible Stream Deck profile.",
                    PluginName, MessageBoxButton.OK, MessageBoxImage.Information);
                return;
            }

            bool hasXlInBuild =
                selected.Any(p => p.DeviceType == ValidationDeviceType) ||
                existingBridgeStates.Any(p => p.DeviceType == ValidationDeviceType);
            // If the temporary test is already installed, keep it in the generated plugin manifest
            // on a real rebuild, but do not present it as a new installation recommendation.
            bool includeTest = hasXlInBuild &&
                (validationAlreadyInstalled || includeValidation.IsChecked == true);
            bool hasProfileCoverage = selected.Count + existingBridgeStates.Count >= 2;
            bool hasPageCoverage = selected.Any(p => p.Pages.Count > 1) ||
                                   ExistingBridgeHasMultiplePages(existingBridgeStates);

            if (!includeTest && (!hasProfileCoverage || !hasPageCoverage))
            {
                bool continueLimited = ShowEnglishConfirm(
                    window,
                    "Limited validation",
                    "Without the temporary validation profile, this setup cannot fully test both profile switching and page switching.\n\nContinue with limited validation?",
                    "Continue",
                    "Go back");
                if (!continueLimited)
                    return;
            }

            try
            {
                HashSet<string> beforeIds = new HashSet<string>(
                    ScanProfiles().Select(p => p.Id),
                    StringComparer.OrdinalIgnoreCase);

                generate.IsEnabled = false;
                generate.Content = "Generating…";

                string installer = BuildBridgePlugin(selected, includeTest);
                BridgeState generatedState = LoadState();

                SaveWindowPlacement(window, "setup");
                window.Hide();
                bool fullValidationAvailable = includeTest || (hasProfileCoverage && hasPageCoverage);
                ShowInstallValidationWindow(installer, generatedState, selected, beforeIds, fullValidationAvailable);
                window.Close();
            }
            catch (Exception ex)
            {
                refreshGenerateState();
                CPH.LogError("[SD Bridge] Build failed: " + ex);
                MessageBox.Show(window,
                    "Generation failed:\n\n" + ex.Message,
                    PluginName, MessageBoxButton.OK, MessageBoxImage.Error);
            }
        };

        window.ShowDialog();
        return true;
    }

    private bool ExistingBridgeHasMultiplePages(List<BridgeProfileState> states)
    {
        foreach (BridgeProfileState b in states ?? new List<BridgeProfileState>())
        {
            ProfileInfo live = FindLiveBridgeProfile(b);
            if (live != null && live.Pages.Count > 1)
                return true;
        }
        return false;
    }

    private void ShowInstallValidationWindow(string installer, BridgeState generatedState,
        List<ProfileInfo> newlySelectedSources, HashSet<string> beforeIds, bool canFullValidate)
    {
        Window window = CreateWindow("SD Bridge", 920, 720);
        EnableWindowPlacement(window, "setup");

        Grid root = new Grid { Margin = new Thickness(14) };
        root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        SetWindowContent(window, root);

        Grid header = new Grid { Margin = new Thickness(2, 2, 2, 14) };
        header.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        header.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        StackPanel titleBlock = new StackPanel();
        titleBlock.Children.Add(new TextBlock
        {
            Text = "SD Bridge",
            FontSize = 18,
            FontWeight = FontWeights.SemiBold,
            Foreground = Brushes.White
        });
        titleBlock.Children.Add(new TextBlock
        {
            Text = "Streamer.bot ↔ Stream Deck profile/page bridge",
            FontSize = 11.5,
            Foreground = ThemeMuted(),
            Margin = new Thickness(0, 3, 0, 0)
        });
        Grid.SetColumn(titleBlock, 0);
        header.Children.Add(titleBlock);

        TextBlock globalStatus = new TextBlock
        {
            Text = "● Waiting",
            Foreground = ThemeWarning(),
            FontSize = 11.5,
            FontWeight = FontWeights.SemiBold,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(globalStatus, 1);
        header.Children.Add(globalStatus);

        Grid.SetRow(header, 0);
        root.Children.Add(header);

        ScrollViewer scroll = new ScrollViewer
        {
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
        };
        StackPanel content = new StackPanel();
        scroll.Content = content;
        Grid.SetRow(scroll, 1);
        root.Children.Add(scroll);

        // When a new workflow section becomes visible, keep it in view automatically.
        Action scrollBottom = delegate
        {
            window.Dispatcher.BeginInvoke(new Action(delegate
            {
                scroll.UpdateLayout();
                scroll.ScrollToEnd();
            }));
        };

        string lastVisualStage = "";

        // INSTALLATION PANEL
        Border installPanel = MakePanel(new Thickness(0, 0, 0, 12));
        StackPanel installStack = new StackPanel();
        installPanel.Child = installStack;

        installStack.Children.Add(new TextBlock
        {
            Text = "Plugin installation",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold,
            FontSize = 14
        });

        Border alert = new Border
        {
            Background = ThemeControl(),
            BorderBrush = ThemeBorder(),
            BorderThickness = new Thickness(1),
            CornerRadius = new CornerRadius(5),
            Padding = new Thickness(12),
            Margin = new Thickness(0, 10, 0, 10)
        };
        StackPanel alertStack = new StackPanel();
        alertStack.Children.Add(new TextBlock
        {
            Text = "IMPORTANT — in the Stream Deck window, click “Install profiles”.",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold
        });
        alertStack.Children.Add(new TextBlock
        {
            Text = "These imported copies are required for Streamer.bot to switch directly between profiles and pages.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 4, 0, 0)
        });
        alert.Child = alertStack;
        installStack.Children.Add(alert);

        TextBlock installerPath = new TextBlock
        {
            Text = "Generated file: " + installer,
            Foreground = ThemeMuted2(),
            FontSize = 10.5,
            TextWrapping = TextWrapping.Wrap
        };
        installStack.Children.Add(installerPath);

        content.Children.Add(installPanel);

        // DETECTION PANEL
        Border detectPanel = MakePanel(new Thickness(0, 0, 0, 12));
        StackPanel detectStack = new StackPanel();
        detectPanel.Child = detectStack;

        Grid detectHeader = new Grid { Margin = new Thickness(0, 0, 0, 8) };
        detectHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        detectHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        TextBlock detectTitle = new TextBlock
        {
            Text = "Imported profiles",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold,
            FontSize = 14
        };
        Grid.SetColumn(detectTitle, 0);
        detectHeader.Children.Add(detectTitle);

        TextBlock watching = new TextBlock
        {
            Text = "● Watching",
            Foreground = ThemeAccent(),
            FontSize = 11.5
        };
        Grid.SetColumn(watching, 1);
        detectHeader.Children.Add(watching);

        detectStack.Children.Add(detectHeader);

        StackPanel profileStatus = new StackPanel();
        detectStack.Children.Add(profileStatus);

        TextBlock workflowStatus = new TextBlock
        {
            Text = "The workflow will resume automatically as soon as all expected profiles are detected.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 6, 0, 0)
        };
        detectStack.Children.Add(workflowStatus);

        content.Children.Add(detectPanel);

        // VALIDATION PANEL
        Border validationPanel = MakePanel(new Thickness(0, 0, 0, 12));
        StackPanel validationStack = new StackPanel();
        validationPanel.Child = validationStack;

        Grid validationHeader = new Grid();
        validationHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        validationHeader.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        StackPanel validationTitleBlock = new StackPanel();
        validationTitleBlock.Children.Add(new TextBlock
        {
            Text = "Automatic validation",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold,
            FontSize = 14
        });
        validationTitleBlock.Children.Add(new TextBlock
        {
            Text = "The Stream Deck will switch across several profiles and pages, then return to your first real [Bridge] profile.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 3, 20, 0)
        });
        Grid.SetColumn(validationTitleBlock, 0);
        validationHeader.Children.Add(validationTitleBlock);

        Button startTest = MakeButton("▶  Start test", 138, "primary");
        startTest.IsEnabled = false;
        Grid.SetColumn(startTest, 1);
        validationHeader.Children.Add(startTest);
        validationStack.Children.Add(validationHeader);

        TextBlock testStatus = new TextBlock
        {
            Text = "Waiting for installation.",
            Foreground = ThemeMuted2(),
            FontSize = 11.5,
            Margin = new Thickness(0, 12, 0, 0),
            TextWrapping = TextWrapping.Wrap
        };
        validationStack.Children.Add(testStatus);

        StackPanel confirmationPanel = new StackPanel
        {
            Visibility = Visibility.Collapsed,
            Margin = new Thickness(0, 12, 0, 0)
        };
        confirmationPanel.Children.Add(new Border
        {
            Height = 1,
            Background = ThemeBorder(),
            Margin = new Thickness(0, 0, 0, 12)
        });
        confirmationPanel.Children.Add(new TextBlock
        {
            Text = "Did the profile and page changes display correctly on the physical Stream Deck?",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 0, 0, 8)
        });
        StackPanel confirmationButtons = new StackPanel { Orientation = Orientation.Horizontal };
        Button confirmYes = MakeButton("Yes, everything worked", 160, "primary");
        Button confirmNo = MakeButton("No / something was wrong", 170, "secondary");
        confirmationButtons.Children.Add(confirmYes);
        confirmationButtons.Children.Add(confirmNo);
        confirmationPanel.Children.Add(confirmationButtons);
        validationStack.Children.Add(confirmationPanel);

        content.Children.Add(validationPanel);

        // CLEANUP PANEL
        Border cleanupPanel = MakePanel(new Thickness(0, 0, 0, 12));
        cleanupPanel.Visibility = Visibility.Collapsed;
        StackPanel cleanupStack = new StackPanel();
        cleanupPanel.Child = cleanupStack;

        cleanupStack.Children.Add(new TextBlock
        {
            Text = "Cleanup",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold,
            FontSize = 14
        });
        cleanupStack.Children.Add(new TextBlock
        {
            Text = "Validation is complete. Automatic removal will temporarily close the Stream Deck app, back up and remove the selected profile folders, then restart Stream Deck when possible. You can also keep them and remove them manually later.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 3, 0, 10)
        });

        Grid originalsRow = new Grid { Margin = new Thickness(0, 4, 0, 4) };
        originalsRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        originalsRow.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        StackPanel originalsInfo = new StackPanel();
        originalsInfo.Children.Add(new TextBlock
        {
            Text = "Original non-bridged profiles",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold
        });
        originalsInfo.Children.Add(new TextBlock
        {
            Text = "Only [Bridge] versions support profile/page navigation. Stream Deck will be closed automatically, the originals will be backed up and removed, then Stream Deck will be restarted when possible.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 3, 20, 0)
        });
        Grid.SetColumn(originalsInfo, 0);
        originalsRow.Children.Add(originalsInfo);

        StackPanel originalsButtons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            VerticalAlignment = VerticalAlignment.Center
        };
        Button keepOriginals = MakeButton("Keep", 92, "secondary");
        Button removeOriginals = MakeButton("Remove now", 142, "secondary");
        keepOriginals.ToolTip = "You can remove them manually later. Only bridged profiles support profile/page navigation.";
        originalsButtons.Children.Add(keepOriginals);
        originalsButtons.Children.Add(removeOriginals);
        Grid.SetColumn(originalsButtons, 1);
        originalsRow.Children.Add(originalsButtons);
        cleanupStack.Children.Add(MakeListRow(originalsRow));

        Grid testRow = new Grid { Margin = new Thickness(0, 4, 0, 4) };
        testRow.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        testRow.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        StackPanel testInfo = new StackPanel();
        testInfo.Children.Add(new TextBlock
        {
            Text = "Bridge Validation Test",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold
        });
        testInfo.Children.Add(new TextBlock
        {
            Text = "Temporary profile no longer needed after validation. Stream Deck will be closed and restarted automatically during removal.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            Margin = new Thickness(0, 3, 20, 0)
        });
        Grid.SetColumn(testInfo, 0);
        testRow.Children.Add(testInfo);

        StackPanel testButtons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            VerticalAlignment = VerticalAlignment.Center
        };
        Button keepTest = MakeButton("Keep", 92, "secondary");
        Button removeTest = MakeButton("Remove now", 142, "secondary");
        testButtons.Children.Add(keepTest);
        testButtons.Children.Add(removeTest);
        Grid.SetColumn(testButtons, 1);
        testRow.Children.Add(testButtons);
        cleanupStack.Children.Add(MakeListRow(testRow));

        TextBlock cleanupStatus = new TextBlock
        {
            Text = "",
            Foreground = ThemeAccent(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 8, 0, 0)
        };
        cleanupStack.Children.Add(cleanupStatus);

        content.Children.Add(cleanupPanel);

        // FOOTER
        Grid footer = new Grid { Margin = new Thickness(2, 12, 2, 0) };
        footer.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        footer.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        TextBlock footerStatus = new TextBlock
        {
            Text = "Waiting for Stream Deck…",
            Foreground = ThemeMuted2(),
            FontSize = 11,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(footerStatus, 0);
        footer.Children.Add(footerStatus);

        StackPanel footerButtons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Right
        };
        Button recoverMissing = MakeButton("Install missing", 132, "secondary");
        Button diagnostics = MakeButton("Diagnostics", 112, "secondary");
        Button verify = MakeButton("↻  Verify", 102, "secondary");
        Button close = MakeButton("Close", 88, "secondary");
        footerButtons.Children.Add(recoverMissing);
        footerButtons.Children.Add(diagnostics);
        footerButtons.Children.Add(verify);
        footerButtons.Children.Add(close);
        Grid.SetColumn(footerButtons, 1);
        footer.Children.Add(footerButtons);

        Grid.SetRow(footer, 2);
        root.Children.Add(footer);

        Action verifyAction = delegate
        {
            InstallationCheckResult result = CheckInstalledProfiles(generatedState);
            string companionIssue;
            bool companionReady = CompanionIsCurrent(generatedState, out companionIssue);
            RenderInstallationStatus(profileStatus, result);
            recoverMissing.IsEnabled = companionReady && result.Statuses.Any(x => x.Live == null);

            string visualStage = companionReady && result.AllReady ? "ready" :
                (result.HasMismatch ? "error" : "waiting");
            if (!string.Equals(lastVisualStage, visualStage, StringComparison.Ordinal))
            {
                lastVisualStage = visualStage;
                scrollBottom();
            }

            if (!companionReady)
            {
                workflowStatus.Text = companionIssue;
                workflowStatus.Foreground = ThemeWarning();
                globalStatus.Text = "● Plugin update required";
                globalStatus.Foreground = ThemeWarning();
                footerStatus.Text = "Companion is not current — Verify will recheck";
                footerStatus.Foreground = ThemeMuted2();
                startTest.IsEnabled = false;
            }
            else if (result.AllReady)
            {
                workflowStatus.Text = "All expected profiles are present and their page structure matches.";
                workflowStatus.Foreground = ThemeAccent();
                globalStatus.Text = "● Ready to validate";
                globalStatus.Foreground = ThemeAccent();
                footerStatus.Text = "Installation verified";
                footerStatus.Foreground = ThemeAccent();
                testStatus.Text = "Ready. Start the test and watch the physical Stream Deck.";
                testStatus.Foreground = ThemeMuted();
                startTest.IsEnabled = true;
            }
            else if (result.HasMismatch)
            {
                workflowStatus.Text = "A profile has a different page structure. Missing profiles can be requested via Install missing. Original profiles will not be removed.";
                workflowStatus.Foreground = ThemeDanger();
                globalStatus.Text = "● Verification error";
                globalStatus.Foreground = ThemeDanger();
                footerStatus.Text = "Verification failed";
                footerStatus.Foreground = ThemeDanger();
                startTest.IsEnabled = false;
            }
            else
            {
                int missing = result.Statuses.Count(x => x.Live == null);
                workflowStatus.Text = missing.ToString(CultureInfo.InvariantCulture) +
                    " profile(s) are missing. Verify only rescans the folders; click Install missing to request installation through the Stream Deck SDK.";
                workflowStatus.Foreground = ThemeWarning();
                globalStatus.Text = "● Missing profiles";
                globalStatus.Foreground = ThemeWarning();
                footerStatus.Text = "Waiting for " + missing.ToString(CultureInfo.InvariantCulture) + " profile(s)…";
                footerStatus.Foreground = ThemeMuted2();
                startTest.IsEnabled = false;
            }
        };

        // Installation via the documented Stream Deck SDK. Do not manipulate
        // Elgato's on-disk profile database or force-restart the application.
        // A switchToProfile for a bundled but missing profile should prompt the
        // user to install that profile. One request at a time avoids dialog races.
        recoverMissing.Click += delegate
        {
            InstallationCheckResult result = CheckInstalledProfiles(generatedState);
            ProfileInstallStatus missing = result.Statuses.FirstOrDefault(x => x.Live == null);
            if (missing == null)
            {
                verifyAction();
                return;
            }
            string companionIssue;
            if (!CompanionIsCurrent(generatedState, out companionIssue))
            {
                workflowStatus.Text = companionIssue;
                workflowStatus.Foreground = ThemeDanger();
                footerStatus.Text = "Plugin installation is incomplete";
                footerStatus.Foreground = ThemeDanger();
                return;
            }
            string commandPath;
            int count = Math.Max(1, missing.Expected.ExpectedPageCount);
            string firstPage = missing.Expected.ExpectedPages != null && missing.Expected.ExpectedPages.Count > 0
                ? missing.Expected.ExpectedPages[0] : "Page 1";
            if (QueueSwitchInternal(missing.Expected, 1, firstPage, count, out commandPath))
            {
                workflowStatus.Text = "Installation requested for '" + missing.Expected.BridgeName +
                    "'. Accept the Stream Deck profile-installation prompt, if shown. This command may switch the active profile. If nothing appears, open Diagnostics and inspect the plugin runtime log.";
                workflowStatus.Foreground = ThemeWarning();
                footerStatus.Text = "Native profile installation requested — not yet confirmed";
                footerStatus.Foreground = ThemeWarning();
            }
            else
            {
                workflowStatus.Text = "Unable to send the installation request. Check Streamer.bot logs.";
                workflowStatus.Foreground = ThemeDanger();
            }
        };

        diagnostics.Click += delegate
        {
            try
            {
                InstallationCheckResult result = CheckInstalledProfiles(generatedState);
                string reportPath = CreateValidationFailureReport(generatedState, installer,
                    canFullValidate, new List<string> { "Installation stuck / profiles missing" },
                    "On-demand report before automatic validation.", result);
                RevealFileInExplorer(reportPath);
                footerStatus.Text = "Diagnostic report created on Desktop";
                footerStatus.Foreground = ThemeAccent();
            }
            catch (Exception ex)
            {
                footerStatus.Text = "Could not create report: " + ex.Message;
                footerStatus.Foreground = ThemeDanger();
                CPH.LogError("[SD Bridge] On-demand diagnostic report failed: " + ex);
            }
        };

        verify.Click += delegate { verifyAction(); };
        close.Click += delegate { window.Close(); };

        startTest.Click += delegate
        {
            InstallationCheckResult result = CheckInstalledProfiles(generatedState);
            string companionIssue;
            if (!result.AllReady || !CompanionIsCurrent(generatedState, out companionIssue))
            {
                verifyAction();
                return;
            }

            startTest.IsEnabled = false;
            verify.IsEnabled = false;
            confirmationPanel.Visibility = Visibility.Collapsed;
            cleanupPanel.Visibility = Visibility.Collapsed;

            testStatus.Text = "Test running — watch the physical Stream Deck.";
            testStatus.Foreground = ThemeWarning();
            globalStatus.Text = "● Validation running";
            globalStatus.Foreground = ThemeWarning();
            footerStatus.Text = "Profile/page switching sequence in progress…";
            footerStatus.Foreground = ThemeWarning();

            Thread worker = new Thread(new ThreadStart(delegate
            {
                bool ok = RunAutomaticValidation(generatedState, window, testStatus);
                window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    verify.IsEnabled = true;
                    startTest.IsEnabled = true;

                    if (ok)
                    {
                        testStatus.Text = "Automatic sequence complete. Confirm what you saw on the Stream Deck.";
                        testStatus.Foreground = ThemeAccent();
                        globalStatus.Text = "● Confirmation required";
                        globalStatus.Foreground = ThemeAccent();
                        footerStatus.Text = "Waiting for visual confirmation";
                        footerStatus.Foreground = ThemeAccent();
                        confirmationPanel.Visibility = Visibility.Visible;
                        scrollBottom();
                    }
                    else
                    {
                        testStatus.Text = "The automatic test failed or a command was not consumed. No original profile will be removed.";
                        testStatus.Foreground = ThemeDanger();
                        globalStatus.Text = "● Validation failed";
                        globalStatus.Foreground = ThemeDanger();
                        footerStatus.Text = "Validation failed";
                        footerStatus.Foreground = ThemeDanger();
                    }
                }));
            }));
            worker.IsBackground = true;
            worker.Start();
        };

        confirmYes.Click += delegate
        {
            confirmationPanel.Visibility = Visibility.Collapsed;

            if (canFullValidate)
            {
                generatedState.ValidationPassed = true;
                SaveState(generatedState);

                cleanupPanel.Visibility = Visibility.Visible;
                scrollBottom();
                globalStatus.Text = "● Validated";
                globalStatus.Foreground = ThemeAccent();
                footerStatus.Text = "Bridge validated";
                footerStatus.Foreground = ThemeAccent();
                cleanupStatus.Text = "Full validation passed.";
            }
            else
            {
                cleanupPanel.Visibility = Visibility.Collapsed;
                testStatus.Text = "The limited test was confirmed, but it does not cover both profile switching and page switching. Original profiles will be kept.";
                testStatus.Foreground = ThemeWarning();
                globalStatus.Text = "● Limited validation";
                globalStatus.Foreground = ThemeWarning();
            }
        };

        confirmNo.Click += delegate
        {
            confirmationPanel.Visibility = Visibility.Collapsed;
            cleanupPanel.Visibility = Visibility.Collapsed;
            testStatus.Text = "Validation was not confirmed. No original profile will be removed.";
            testStatus.Foreground = ThemeDanger();
            globalStatus.Text = "● Not validated";
            globalStatus.Foreground = ThemeDanger();
            footerStatus.Text = "Collecting diagnostic feedback…";
            footerStatus.Foreground = ThemeWarning();

            string reportPath = ShowValidationFailureQuestionnaire(
                window,
                generatedState,
                installer,
                canFullValidate);

            if (!string.IsNullOrWhiteSpace(reportPath))
            {
                testStatus.Text = "Validation was not confirmed. A diagnostic report was created on the Desktop. No original profile will be removed; you can run the test again.";
                footerStatus.Text = "Diagnostic report created";
                footerStatus.Foreground = ThemeAccent();
            }
            else
            {
                testStatus.Text = "Validation was not confirmed. No original profile will be removed. You can run the test again.";
                footerStatus.Text = "Validation not confirmed";
                footerStatus.Foreground = ThemeDanger();
            }
        };

        removeOriginals.Click += delegate
        {
            List<string> paths = newlySelectedSources
                .Where(p => !string.IsNullOrWhiteSpace(p.SourcePath) && Directory.Exists(p.SourcePath))
                .Select(p => p.SourcePath)
                .Distinct(StringComparer.OrdinalIgnoreCase)
                .ToList();

            if (paths.Count == 0)
            {
                cleanupStatus.Text = "No newly converted original profile is available to remove.";
                scrollBottom();
                return;
            }

            removeOriginals.IsEnabled = false;
            keepOriginals.IsEnabled = false;

            Action<string> pushStatus = delegate(string message)
            {
                window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    cleanupStatus.Text = message;
                    scrollBottom();
                }));
            };

            Thread cleanupWorker = new Thread(new ThreadStart(delegate
            {
                string backup;
                string resultMessage;
                bool ok = RemoveProfilesSafely(paths, "Originals", out backup, out resultMessage, pushStatus);

                window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    cleanupStatus.Text = resultMessage;
                    cleanupStatus.Foreground = ok ? ThemeAccent() : ThemeDanger();

                    if (!ok)
                    {
                        removeOriginals.IsEnabled = true;
                        keepOriginals.IsEnabled = true;
                    }

                    scrollBottom();
                }));
            }));
            cleanupWorker.IsBackground = true;
            cleanupWorker.Start();
        };

        keepOriginals.Click += delegate
        {
            cleanupStatus.Text = "Original profiles kept. You can remove them manually later.";
            cleanupStatus.Foreground = ThemeMuted();
            removeOriginals.IsEnabled = false;
            keepOriginals.IsEnabled = false;
            scrollBottom();
        };

        removeTest.Click += delegate
        {
            BridgeProfileState testState = (generatedState.Profiles ?? new List<BridgeProfileState>())
                .FirstOrDefault(p => p.IsValidationTest);
            ProfileInfo liveTest = testState == null ? null : FindLiveProfileForState(testState);

            if (liveTest == null || !Directory.Exists(liveTest.SourcePath))
            {
                cleanupStatus.Text = "The temporary validation profile is already absent.";
                removeTest.IsEnabled = false;
                keepTest.IsEnabled = false;
                scrollBottom();
                return;
            }

            removeTest.IsEnabled = false;
            keepTest.IsEnabled = false;

            Action<string> pushStatus = delegate(string message)
            {
                window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    cleanupStatus.Text = message;
                    scrollBottom();
                }));
            };

            Thread cleanupWorker = new Thread(new ThreadStart(delegate
            {
                string backup;
                string resultMessage;
                bool ok = RemoveProfilesSafely(
                    new List<string> { liveTest.SourcePath },
                    "ValidationTest",
                    out backup,
                    out resultMessage,
                    pushStatus);

                window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    cleanupStatus.Text = resultMessage;
                    cleanupStatus.Foreground = ok ? ThemeAccent() : ThemeDanger();

                    if (ok)
                    {
                        generatedState.IncludesValidationProfile = false;
                        generatedState.ValidationPassed = true;
                        generatedState.Profiles = (generatedState.Profiles ?? new List<BridgeProfileState>())
                            .Where(p => !p.IsValidationTest)
                            .ToList();
                        SaveState(generatedState);
                    }
                    else
                    {
                        removeTest.IsEnabled = true;
                        keepTest.IsEnabled = true;
                    }

                    scrollBottom();
                }));
            }));
            cleanupWorker.IsBackground = true;
            cleanupWorker.Start();
        };

        keepTest.Click += delegate
        {
            cleanupStatus.Text = "Temporary validation profile kept. You can remove it manually later.";
            cleanupStatus.Foreground = ThemeMuted();
            removeTest.IsEnabled = false;
            keepTest.IsEnabled = false;
            scrollBottom();
        };

        HashSet<string> autoRequestedKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        DateTime installerOpenedAt = DateTime.UtcNow;

        window.Loaded += delegate
        {
            installerOpenedAt = DateTime.UtcNow;
            // Render installed state before launching the installer: a previous
            // build can have 2/3 profiles already present, but the new one missing.
            verifyAction();
            try
            {
                ProcessStartInfo psi = new ProcessStartInfo(installer);
                psi.UseShellExecute = true;
                Process.Start(psi);
            }
            catch (Exception ex)
            {
                workflowStatus.Text = "Could not launch the installer automatically: " + ex.Message;
                workflowStatus.Foreground = ThemeDanger();
                globalStatus.Text = "● Error";
                globalStatus.Foreground = ThemeDanger();
            }

            Thread watcher = new Thread(new ThreadStart(delegate
            {
                for (int i = 0; ; i++)
                {
                    // WPF Window.IsVisible must be read on the UI Dispatcher.
                    // The original code accessed it cross-thread and could stop
                    // the watcher with InvalidOperationException.
                    bool stillVisible = false;
                    try
                    {
                        stillVisible = window.Dispatcher.Invoke(
                            new Func<bool>(delegate { return window.IsVisible; }));
                    }
                    catch { return; }
                    if (!stillVisible) return;

                    InstallationCheckResult result = CheckInstalledProfiles(generatedState);
                    string companionIssue;
                    bool companionReady = CompanionIsCurrent(generatedState, out companionIssue);

                    window.Dispatcher.BeginInvoke(new Action(delegate
                    {
                        RenderInstallationStatus(profileStatus, result);
                        recoverMissing.IsEnabled = companionReady && result.Statuses.Any(x => x.Live == null);

                        string visualStage = companionReady && result.AllReady ? "ready" :
                            (result.HasMismatch ? "error" : "waiting");
                        if (!string.Equals(lastVisualStage, visualStage, StringComparison.Ordinal))
                        {
                            lastVisualStage = visualStage;
                            scrollBottom();
                        }

                        if (!companionReady)
                        {
                            workflowStatus.Text = companionIssue;
                            workflowStatus.Foreground = ThemeWarning();
                            globalStatus.Text = "● Plugin update required";
                            globalStatus.Foreground = ThemeWarning();
                            footerStatus.Text = "Install/update the generated companion first";
                            footerStatus.Foreground = ThemeMuted2();
                            startTest.IsEnabled = false;
                        }
                        else if (result.AllReady)
                        {
                            workflowStatus.Text = "Installation detected. All expected profiles are present.";
                            workflowStatus.Foreground = ThemeAccent();
                            globalStatus.Text = "● Ready to validate";
                            globalStatus.Foreground = ThemeAccent();
                            footerStatus.Text = "Installation verified";
                            footerStatus.Foreground = ThemeAccent();
                            testStatus.Text = "Ready. Start the test and watch the physical Stream Deck.";
                            startTest.IsEnabled = true;
                        }
                        else if (result.HasMismatch)
                        {
                            workflowStatus.Text = "An imported profile does not match the expected structure. Open Diagnostics to investigate.";
                            workflowStatus.Foreground = ThemeDanger();
                            globalStatus.Text = "● Verification error";
                            globalStatus.Foreground = ThemeDanger();
                            footerStatus.Text = "Profile verification failed";
                            footerStatus.Foreground = ThemeDanger();
                            startTest.IsEnabled = false;
                        }
                        else
                        {
                            int missing = result.Statuses.Count(x => x.Live == null);
                            workflowStatus.Text = missing.ToString(CultureInfo.InvariantCulture) +
                                " profile(s) missing. SD Bridge will request native installation after plugin update.";
                            workflowStatus.Foreground = ThemeWarning();

                            // On plugin upgrades AutoInstall may not re-run. Send exactly
                            // ONE switchToProfile for each missing bundled profile, and
                            // move to the next only after the previous profile arrives.
                            // Let Elgato finish its original import prompt first.
                            if (missing > 0 && !result.HasMismatch &&
                                (DateTime.UtcNow - installerOpenedAt).TotalSeconds >= 5)
                            {
                                ProfileInstallStatus next = result.Statuses.FirstOrDefault(x =>
                                    x.Live == null && !autoRequestedKeys.Contains(x.Expected.Key));
                                bool outstanding = result.Statuses.Any(x =>
                                    x.Live == null && autoRequestedKeys.Contains(x.Expected.Key));
                                if (next != null && !outstanding)
                                {
                                    autoRequestedKeys.Add(next.Expected.Key);
                                    string path;
                                    string label = next.Expected.ExpectedPages != null && next.Expected.ExpectedPages.Count > 0
                                        ? next.Expected.ExpectedPages[0] : "Page 1";
                                    if (QueueSwitchInternal(next.Expected, 1, label,
                                        Math.Max(1, next.Expected.ExpectedPageCount), out path))
                                    {
                                        workflowStatus.Text = "Requested native installation of '" + next.Expected.BridgeName +
                                            "'. Accept Elgato's profile prompt, if shown. Install missing retries this request.";
                                        footerStatus.Text = "Profile import requested — waiting for confirmation";
                                    }
                                    else autoRequestedKeys.Remove(next.Expected.Key);
                                }
                            }
                        }
                    }));

                    if (companionReady && result.AllReady)
                        return;

                    Thread.Sleep(i < 180 ? 1000 : 3000);
                }
            }));
            watcher.IsBackground = true;
            watcher.Start();
        };

        window.ShowDialog();
    }

    private InstallationCheckResult CheckInstalledProfiles(BridgeState state)
    {
        InstallationCheckResult result = new InstallationCheckResult();
        List<ProfileInfo> liveProfiles = ScanProfiles();

        foreach (BridgeProfileState expected in state.Profiles ?? new List<BridgeProfileState>())
        {
            ProfileInstallStatus status = new ProfileInstallStatus();
            status.Expected = expected;
            status.Live = FindLiveProfileForState(expected, liveProfiles);
            if (status.Live == null)
            {
                status.Message = "not detected";
                status.Ready = false;
            }
            else
            {
                int expectedCount = expected.ExpectedPageCount > 0 ? expected.ExpectedPageCount : 1;
                if (status.Live.Pages.Count != expectedCount)
                {
                    status.Message = "detected, but page count mismatch (expected " + expectedCount + ", found " + status.Live.Pages.Count + ")";
                    status.Mismatch = true;
                }
                else if (!expected.IsValidationTest && expected.ExpectedPages != null && expected.ExpectedPages.Count == expectedCount &&
                         !PageListsEqual(expected.ExpectedPages, status.Live.Pages))
                {
                    status.Message = "detected, but page names/order differ from the generated copy";
                    status.Mismatch = true;
                }
                else
                {
                    status.Message = "ready — " + status.Live.Pages.Count + " page(s)";
                    status.Ready = true;
                }
            }
            result.Statuses.Add(status);
        }

        result.AllReady = result.Statuses.Count > 0 && result.Statuses.All(x => x.Ready);
        result.HasMismatch = result.Statuses.Any(x => x.Mismatch);
        return result;
    }

    private bool PageListsEqual(List<string> a, List<string> b)
    {
        if (a == null || b == null || a.Count != b.Count)
            return false;
        for (int i = 0; i < a.Count; i++)
        {
            if (!string.Equals(a[i] ?? "", b[i] ?? "", StringComparison.OrdinalIgnoreCase))
                return false;
        }
        return true;
    }

    private void RenderInstallationStatus(StackPanel panel, InstallationCheckResult result)
    {
        panel.Children.Clear();

        foreach (ProfileInstallStatus s in result.Statuses)
        {
            Grid row = new Grid { Margin = new Thickness(0, 4, 0, 4) };
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
            row.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

            TextBlock dot = new TextBlock
            {
                Text = "●",
                Foreground = s.Ready ? ThemeAccent() : (s.Mismatch ? ThemeDanger() : ThemeMuted2()),
                Width = 20,
                VerticalAlignment = VerticalAlignment.Top,
                Margin = new Thickness(2, 1, 8, 0)
            };
            Grid.SetColumn(dot, 0);
            row.Children.Add(dot);

            StackPanel info = new StackPanel();
            info.Children.Add(new TextBlock
            {
                Text = s.Expected.BridgeName,
                Foreground = Brushes.White,
                FontWeight = FontWeights.SemiBold
            });
            info.Children.Add(new TextBlock
            {
                Text = s.Message,
                Foreground = s.Ready ? ThemeAccent() : (s.Mismatch ? ThemeDanger() : ThemeMuted()),
                FontSize = 11.5,
                TextWrapping = TextWrapping.Wrap,
                Margin = new Thickness(0, 3, 0, 0)
            });
            Grid.SetColumn(info, 1);
            row.Children.Add(info);

            TextBlock status = new TextBlock
            {
                Text = s.Ready ? "Ready" : (s.Mismatch ? "Error" : "Waiting"),
                Foreground = s.Ready ? ThemeAccent() : (s.Mismatch ? ThemeDanger() : ThemeMuted2()),
                FontSize = 11.5,
                Margin = new Thickness(12, 1, 2, 0),
                VerticalAlignment = VerticalAlignment.Top
            };
            Grid.SetColumn(status, 2);
            row.Children.Add(status);

            panel.Children.Add(MakeListRow(row));
        }
    }

    private bool RunAutomaticValidation(BridgeState state, Window window, TextBlock status)
    {
        try
        {
            List<ValidationStep> steps = BuildValidationSteps(state);
            if (steps.Count == 0)
                return false;

            for (int i = 0; i < steps.Count; i++)
            {
                ValidationStep step = steps[i];
                int index = i + 1;
                window.Dispatcher.BeginInvoke(new Action(delegate
                {
                    status.Text = "Test " + index.ToString(CultureInfo.InvariantCulture) + "/" +
                                  steps.Count.ToString(CultureInfo.InvariantCulture) + " — " +
                                  step.Profile.BridgeName + " → page " + step.PageNumber.ToString(CultureInfo.InvariantCulture) +
                                  " (" + step.PageName + ")";
                    status.Foreground = new SolidColorBrush(Color.FromRgb(255, 205, 90));
                }));

                string commandPath;
                if (!QueueSwitchInternal(step.Profile, step.PageNumber, step.PageName, step.PageCount, out commandPath))
                    return false;
                if (!WaitForCommandConsumed(commandPath, 4000))
                {
                    CPH.LogWarn("[SD Bridge] Validation command was not consumed: " + commandPath);
                    return false;
                }
                Thread.Sleep(1600);
            }
            return true;
        }
        catch (Exception ex)
        {
            CPH.LogError("[SD Bridge] Automatic validation failed: " + ex);
            return false;
        }
    }

    private List<ValidationStep> BuildValidationSteps(BridgeState state)
    {
        List<ValidationStep> steps = new List<ValidationStep>();
        Random rnd = new Random(unchecked(Environment.TickCount * 397) ^ DateTime.Now.Millisecond);

        List<BridgeProfileState> realProfiles = (state.Profiles ?? new List<BridgeProfileState>())
            .Where(p => !p.IsValidationTest)
            .Where(p => FindLiveProfileForState(p) != null)
            .OrderBy(p => rnd.Next())
            .Take(3)
            .ToList();

        BridgeProfileState test = (state.Profiles ?? new List<BridgeProfileState>())
            .FirstOrDefault(p => p.IsValidationTest && FindLiveProfileForState(p) != null);

        List<int> testPages = new List<int>();
        if (test != null)
            testPages = PickDistinctPages(ValidationProfilePageCount, 3, rnd);

        if (test != null && testPages.Count > 0)
            AddValidationStep(steps, test, testPages[0]);

        for (int i = 0; i < realProfiles.Count; i++)
        {
            BridgeProfileState p = realProfiles[i];
            ProfileInfo live = FindLiveProfileForState(p);
            if (live == null)
                continue;

            List<int> pages = PickDistinctPages(live.Pages.Count, live.Pages.Count > 1 ? 2 : 1, rnd);
            foreach (int page in pages)
                AddValidationStep(steps, p, page);

            if (test != null && i + 1 < testPages.Count)
                AddValidationStep(steps, test, testPages[i + 1]);
        }

        if (test != null && testPages.Count > 1 && !steps.Any(x => x.Profile.IsValidationTest && x.PageNumber == testPages[testPages.Count - 1]))
            AddValidationStep(steps, test, testPages[testPages.Count - 1]);

        // Always return to the first real bridged profile after the test.
        BridgeProfileState returnProfile = (state.Profiles ?? new List<BridgeProfileState>())
            .FirstOrDefault(p => !p.IsValidationTest && FindLiveProfileForState(p) != null);
        if (returnProfile != null)
            AddValidationStep(steps, returnProfile, 1);

        return steps;
    }

    private void AddValidationStep(List<ValidationStep> steps, BridgeProfileState profile, int pageNumber)
    {
        ProfileInfo live = FindLiveProfileForState(profile);
        if (live == null || live.Pages.Count == 0)
            return;
        pageNumber = Math.Max(1, Math.Min(pageNumber, live.Pages.Count));

        ValidationStep step = new ValidationStep();
        step.Profile = profile;
        step.PageNumber = pageNumber;
        step.PageCount = live.Pages.Count;
        step.PageName = live.Pages[pageNumber - 1];
        steps.Add(step);
    }

    private List<int> PickDistinctPages(int pageCount, int wanted, Random rnd)
    {
        List<int> result = new List<int>();
        if (pageCount <= 0 || wanted <= 0)
            return result;

        List<int> pool = Enumerable.Range(1, pageCount).OrderBy(x => rnd.Next()).ToList();
        foreach (int p in pool.Take(Math.Min(wanted, pageCount)))
            result.Add(p);
        return result;
    }

    private bool WaitForCommandConsumed(string commandPath, int timeoutMs)
    {
        Stopwatch sw = Stopwatch.StartNew();
        while (sw.ElapsedMilliseconds < timeoutMs)
        {
            if (string.IsNullOrWhiteSpace(commandPath) || !File.Exists(commandPath))
                return true;
            Thread.Sleep(50);
        }
        return !File.Exists(commandPath);
    }

    private bool RemoveProfilesSafely(
        List<string> profilePaths,
        string category,
        out string backupRoot,
        out string resultMessage,
        Action<string> statusCallback)
    {
        backupRoot = "";
        resultMessage = "";

        profilePaths = (profilePaths ?? new List<string>())
            .Where(p => !string.IsNullOrWhiteSpace(p) && Directory.Exists(p))
            .Distinct(StringComparer.OrdinalIgnoreCase)
            .ToList();

        if (profilePaths.Count == 0)
        {
            resultMessage = "Nothing to remove.";
            return true;
        }

        bool streamDeckWasRunning = false;
        string streamDeckExe = FindRunningStreamDeckExecutable();
        List<Tuple<string, string>> backups = new List<Tuple<string, string>>();

        Action<string> report = delegate(string message)
        {
            CPH.LogInfo("[SD Bridge] Cleanup: " + message);
            if (statusCallback != null)
            {
                try { statusCallback(message); }
                catch { }
            }
        };

        try
        {
            Process[] running = Process.GetProcessesByName("StreamDeck");
            streamDeckWasRunning = running.Length > 0;
            if (streamDeckWasRunning)
            {
                report("Closing Stream Deck before profile removal…");
                foreach (Process process in running)
                {
                    try { if (!process.HasExited) process.CloseMainWindow(); } catch { }
                }

                Stopwatch closeWait = Stopwatch.StartNew();
                while (closeWait.ElapsedMilliseconds < 2500)
                {
                    if (Process.GetProcessesByName("StreamDeck").Length == 0) break;
                    Thread.Sleep(100);
                }

                foreach (Process process in Process.GetProcessesByName("StreamDeck"))
                {
                    try
                    {
                        if (!process.HasExited)
                        {
                            report("Stream Deck is still running — forcing it to close…");
                            process.Kill();
                            process.WaitForExit(3000);
                        }
                    }
                    catch (Exception killEx)
                    {
                        CPH.LogWarn("[SD Bridge] Could not force-close one Stream Deck process: " + killEx.Message);
                    }
                }

                Stopwatch forceWait = Stopwatch.StartNew();
                while (forceWait.ElapsedMilliseconds < 3000)
                {
                    if (Process.GetProcessesByName("StreamDeck").Length == 0) break;
                    Thread.Sleep(100);
                }
                if (Process.GetProcessesByName("StreamDeck").Length > 0)
                    throw new InvalidOperationException("Stream Deck could not be closed automatically. No profile was removed.");
            }

            backupRoot = Path.Combine(
                PortableDataRoot,
                "Backups",
                DateTime.Now.ToString("yyyy-MM-dd_HH-mm-ss-fff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8),
                category);
            Directory.CreateDirectory(backupRoot);

            // Phase 1: copy and verify every profile. Nothing is deleted until all backups pass.
            report("Creating and verifying safety backups…");
            foreach (string source in profilePaths)
            {
                string name = Path.GetFileName(source.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));
                string destination = Path.Combine(backupRoot, name);
                int n = 2;
                while (Directory.Exists(destination))
                {
                    destination = Path.Combine(backupRoot, name + "-" + n.ToString(CultureInfo.InvariantCulture));
                    n++;
                }
                CopyDirectoryRecursive(source, destination);
                VerifyDirectoryCopy(source, destination);
                backups.Add(Tuple.Create(source, destination));
                CPH.LogInfo("[SD Bridge] Verified backup: " + source + " => " + destination);
            }

            // Phase 2: only now remove originals.
            report("All backups verified. Removing selected profile data…");
            foreach (Tuple<string, string> pair in backups)
            {
                Directory.Delete(pair.Item1, true);
            }

            bool restarted = false;
            if (streamDeckWasRunning)
            {
                report("Profiles removed. Restarting Stream Deck…");
                if (string.IsNullOrWhiteSpace(streamDeckExe) || !File.Exists(streamDeckExe))
                    streamDeckExe = FindInstalledStreamDeckExecutable();
                restarted = TryRestartStreamDeck(streamDeckExe);
            }

            resultMessage = streamDeckWasRunning
                ? (restarted
                    ? "Cleanup complete. Verified safety backup created and Stream Deck restarted. Backup: " + backupRoot
                    : "Cleanup complete. Verified safety backup created. Stream Deck could not be restarted automatically; please start it manually. Backup: " + backupRoot)
                : "Cleanup complete. Verified safety backup created. Backup: " + backupRoot;
            report(resultMessage);
            return true;
        }
        catch (Exception ex)
        {
            CPH.LogError("[SD Bridge] Profile cleanup failed: " + ex);

            // Roll back any source that is missing or no longer matches its verified backup.
            if (backups.Count > 0)
            {
                report("Cleanup failed. Verifying originals and restoring from backups where required…");
                foreach (Tuple<string, string> pair in backups)
                {
                    bool needsRestore = !Directory.Exists(pair.Item1);
                    if (!needsRestore)
                    {
                        try { VerifyDirectoryCopy(pair.Item2, pair.Item1); }
                        catch { needsRestore = true; }
                    }
                    if (!needsRestore) continue;
                    try
                    {
                        if (Directory.Exists(pair.Item1)) Directory.Delete(pair.Item1, true);
                        CopyDirectoryRecursive(pair.Item2, pair.Item1);
                        VerifyDirectoryCopy(pair.Item2, pair.Item1);
                    }
                    catch (Exception restoreEx)
                    {
                        CPH.LogError("[SD Bridge] ROLLBACK FAILED for " + pair.Item1 + ": " + restoreEx);
                    }
                }
            }

            if (streamDeckWasRunning && Process.GetProcessesByName("StreamDeck").Length == 0)
            {
                report("Cleanup failed. Attempting to restart Stream Deck…");
                if (string.IsNullOrWhiteSpace(streamDeckExe) || !File.Exists(streamDeckExe))
                    streamDeckExe = FindInstalledStreamDeckExecutable();
                TryRestartStreamDeck(streamDeckExe);
            }

            resultMessage = "Automatic cleanup failed: " + ex.Message +
                (string.IsNullOrWhiteSpace(backupRoot) ? "" : " Backup retained at: " + backupRoot);
            report(resultMessage);
            return false;
        }
    }

    private void CopyDirectoryRecursive(string source, string destination)
    {
        Directory.CreateDirectory(destination);
        foreach (string dir in Directory.GetDirectories(source, "*", SearchOption.AllDirectories))
        {
            string rel = dir.Substring(source.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            Directory.CreateDirectory(Path.Combine(destination, rel));
        }
        foreach (string file in Directory.GetFiles(source, "*", SearchOption.AllDirectories))
        {
            string rel = file.Substring(source.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);
            string target = Path.Combine(destination, rel);
            Directory.CreateDirectory(Path.GetDirectoryName(target));
            File.Copy(file, target, true);
        }
    }

    private void VerifyDirectoryCopy(string source, string destination)
    {
        Dictionary<string, FileInfo> sourceFiles = Directory.GetFiles(source, "*", SearchOption.AllDirectories)
            .ToDictionary(f => f.Substring(source.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar), f => new FileInfo(f), StringComparer.OrdinalIgnoreCase);
        Dictionary<string, FileInfo> destinationFiles = Directory.GetFiles(destination, "*", SearchOption.AllDirectories)
            .ToDictionary(f => f.Substring(destination.Length).TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar), f => new FileInfo(f), StringComparer.OrdinalIgnoreCase);

        if (sourceFiles.Count != destinationFiles.Count)
            throw new IOException("Backup verification failed: file count mismatch.");

        foreach (KeyValuePair<string, FileInfo> kv in sourceFiles)
        {
            FileInfo dst;
            if (!destinationFiles.TryGetValue(kv.Key, out dst) || dst.Length != kv.Value.Length)
                throw new IOException("Backup verification failed for file: " + kv.Key);
            if (!FilesHaveSameSha256(kv.Value.FullName, dst.FullName))
                throw new IOException("Backup verification hash mismatch for file: " + kv.Key);
        }
    }

    private bool FilesHaveSameSha256(string a, string b)
    {
        using (SHA256 sha = SHA256.Create())
        using (FileStream fa = File.OpenRead(a))
        using (FileStream fb = File.OpenRead(b))
        {
            byte[] ha = sha.ComputeHash(fa);
            byte[] hb = sha.ComputeHash(fb);
            return ha.SequenceEqual(hb);
        }
    }

    private string FindRunningStreamDeckExecutable()
    {
        try
        {
            foreach (Process process in Process.GetProcessesByName("StreamDeck"))
            {
                try
                {
                    if (process.MainModule != null &&
                        !string.IsNullOrWhiteSpace(process.MainModule.FileName) &&
                        File.Exists(process.MainModule.FileName))
                    {
                        return process.MainModule.FileName;
                    }
                }
                catch
                {
                }
            }
        }
        catch
        {
        }

        return FindInstalledStreamDeckExecutable();
    }

    private string FindInstalledStreamDeckExecutable()
    {
        List<string> candidates = new List<string>();

        string programFiles = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);
        if (!string.IsNullOrWhiteSpace(programFiles))
            candidates.Add(Path.Combine(programFiles, "Elgato", "StreamDeck", "StreamDeck.exe"));

        string programFilesX86 = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86);
        if (!string.IsNullOrWhiteSpace(programFilesX86))
            candidates.Add(Path.Combine(programFilesX86, "Elgato", "StreamDeck", "StreamDeck.exe"));

        string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        if (!string.IsNullOrWhiteSpace(localAppData))
        {
            candidates.Add(Path.Combine(localAppData, "Elgato", "StreamDeck", "StreamDeck.exe"));
            candidates.Add(Path.Combine(localAppData, "Programs", "Elgato", "StreamDeck", "StreamDeck.exe"));
        }

        return candidates.FirstOrDefault(File.Exists) ?? "";
    }

    private bool TryRestartStreamDeck(string executablePath)
    {
        if (string.IsNullOrWhiteSpace(executablePath) || !File.Exists(executablePath))
        {
            CPH.LogWarn("[SD Bridge] Stream Deck executable path was not found; automatic restart skipped.");
            return false;
        }

        try
        {
            ProcessStartInfo psi = new ProcessStartInfo(executablePath);
            psi.UseShellExecute = true;
            Process.Start(psi);

            CPH.LogInfo("[SD Bridge] Stream Deck restarted: " + executablePath);
            return true;
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not restart Stream Deck automatically: " + ex.Message);
            return false;
        }
    }

    private class InstallationCheckResult
    {
        public List<ProfileInstallStatus> Statuses = new List<ProfileInstallStatus>();
        public bool AllReady;
        public bool HasMismatch;
    }

    private class ProfileInstallStatus
    {
        public BridgeProfileState Expected;
        public ProfileInfo Live;
        public bool Ready;
        public bool Mismatch;
        public string Message = "";
    }

    private class ValidationStep
    {
        public BridgeProfileState Profile;
        public int PageNumber;
        public int PageCount;
        public string PageName;
    }


    // -------------------------------------------------------------------------
    // VALIDATION FAILURE QUESTIONNAIRE / SUPPORT REPORT
    // -------------------------------------------------------------------------

    private string ShowValidationFailureQuestionnaire(
        Window owner,
        BridgeState state,
        string installer,
        bool canFullValidate)
    {
        string reportPath = "";

        Window dialog = CreateWindow("SD Bridge — Validation feedback", 760, 650);
        try
        {
            dialog.Owner = owner;
            dialog.WindowStartupLocation = WindowStartupLocation.CenterOwner;
        }
        catch
        {
            dialog.WindowStartupLocation = WindowStartupLocation.CenterScreen;
        }

        Grid root = new Grid { Margin = new Thickness(14) };
        root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        SetWindowContent(dialog, root);

        StackPanel header = new StackPanel { Margin = new Thickness(2, 2, 2, 14) };
        header.Children.Add(new TextBlock
        {
            Text = "What went wrong?",
            FontSize = 18,
            FontWeight = FontWeights.SemiBold,
            Foreground = Brushes.White
        });
        header.Children.Add(new TextBlock
        {
            Text = "Check everything you noticed. SD Bridge will create a small diagnostic report you can attach on Discord.",
            FontSize = 11.5,
            Foreground = ThemeMuted(),
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 4, 0, 0)
        });
        Grid.SetRow(header, 0);
        root.Children.Add(header);

        ScrollViewer scroll = new ScrollViewer
        {
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            HorizontalScrollBarVisibility = ScrollBarVisibility.Disabled
        };
        StackPanel content = new StackPanel();
        scroll.Content = content;
        Grid.SetRow(scroll, 1);
        root.Children.Add(scroll);

        Border questionnairePanel = MakePanel(new Thickness(0, 0, 0, 12));
        StackPanel questionnaireStack = new StackPanel();
        questionnairePanel.Child = questionnaireStack;

        string[] symptoms = new[]
        {
            "The Stream Deck did not switch profiles.",
            "The profile changed, but not to the expected profile.",
            "The profile changed, but the page did not change.",
            "The page changed, but not to the expected page.",
            "Only some steps in the automatic sequence worked.",
            "A [Bridge] or temporary validation profile was missing, duplicated, or looked wrong.",
            "Stream Deck disconnected, restarted, froze, or became unresponsive.",
            "The sequence was too fast / I could not verify every step.",
            "Something else / I am not sure."
        };

        List<Tuple<CheckBox, string>> symptomChecks = new List<Tuple<CheckBox, string>>();
        foreach (string symptom in symptoms)
        {
            CheckBox cb = new CheckBox
            {
                Content = symptom,
                Foreground = Brushes.White,
                Margin = new Thickness(2, 5, 2, 5),
                VerticalAlignment = VerticalAlignment.Top
            };
            questionnaireStack.Children.Add(cb);
            symptomChecks.Add(Tuple.Create(cb, symptom));
        }
        content.Children.Add(questionnairePanel);

        Border notesPanel = MakePanel(new Thickness(0, 0, 0, 12));
        StackPanel notesStack = new StackPanel();
        notesPanel.Child = notesStack;
        notesStack.Children.Add(new TextBlock
        {
            Text = "Optional details",
            Foreground = Brushes.White,
            FontWeight = FontWeights.SemiBold,
            FontSize = 13
        });
        notesStack.Children.Add(new TextBlock
        {
            Text = "Add anything useful you saw (for example: which profile/page stayed visible). Do not paste passwords or tokens.",
            Foreground = ThemeMuted(),
            FontSize = 11.5,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 3, 0, 8)
        });
        TextBox notes = new TextBox
        {
            MinHeight = 88,
            MaxHeight = 150,
            AcceptsReturn = true,
            TextWrapping = TextWrapping.Wrap,
            VerticalScrollBarVisibility = ScrollBarVisibility.Auto,
            Background = ThemeControl(),
            Foreground = Brushes.White,
            BorderBrush = ThemeBorder(),
            BorderThickness = new Thickness(1),
            Padding = new Thickness(8)
        };
        notesStack.Children.Add(notes);
        content.Children.Add(notesPanel);

        TextBlock status = new TextBlock
        {
            Text = "The report contains technical version/profile information and a short sanitized runtime log tail. You can review the .txt file before posting it.",
            Foreground = ThemeMuted2(),
            FontSize = 10.8,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(2, 0, 2, 8)
        };
        content.Children.Add(status);

        Grid footer = new Grid { Margin = new Thickness(2, 10, 2, 0) };
        footer.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        footer.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        TextBlock footerHint = new TextBlock
        {
            Text = "No profile will be deleted when validation fails.",
            Foreground = ThemeMuted2(),
            FontSize = 11,
            VerticalAlignment = VerticalAlignment.Center
        };
        Grid.SetColumn(footerHint, 0);
        footer.Children.Add(footerHint);

        StackPanel buttons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Right
        };
        Button cancel = MakeButton("Cancel", 96, "secondary");
        Button generateReport = MakeButton("Create report", 142, "primary");
        buttons.Children.Add(cancel);
        buttons.Children.Add(generateReport);
        Grid.SetColumn(buttons, 1);
        footer.Children.Add(buttons);

        Grid.SetRow(footer, 2);
        root.Children.Add(footer);

        cancel.Click += delegate { dialog.Close(); };

        generateReport.Click += delegate
        {
            List<string> selectedSymptoms = symptomChecks
                .Where(x => x.Item1.IsChecked == true)
                .Select(x => x.Item2)
                .ToList();

            if (selectedSymptoms.Count == 0 && string.IsNullOrWhiteSpace(notes.Text))
            {
                status.Text = "Select at least one item, or add a short note, before creating the report.";
                status.Foreground = ThemeWarning();
                return;
            }

            try
            {
                InstallationCheckResult installation = CheckInstalledProfiles(state);
                reportPath = CreateValidationFailureReport(
                    state,
                    installer,
                    canFullValidate,
                    selectedSymptoms,
                    notes.Text,
                    installation);

                RevealFileInExplorer(reportPath);

                MessageBox.Show(
                    dialog,
                    "Diagnostic report created:\n\n" + reportPath +
                    "\n\nExplorer has been opened with the file selected. Please attach this .txt file in the SD Bridge Discord test/support channel.",
                    "SD Bridge — Report created",
                    MessageBoxButton.OK,
                    MessageBoxImage.Information);

                dialog.Close();
            }
            catch (Exception ex)
            {
                CPH.LogError("[SD Bridge] Could not create validation failure report: " + ex);
                status.Text = "Could not create the report: " + ex.Message;
                status.Foreground = ThemeDanger();
            }
        };

        dialog.ShowDialog();
        return reportPath;
    }

    private string CreateValidationFailureReport(
        BridgeState state,
        string installer,
        bool canFullValidate,
        List<string> symptoms,
        string notes,
        InstallationCheckResult installation)
    {
        string desktop = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
        if (string.IsNullOrWhiteSpace(desktop) || !Directory.Exists(desktop))
            desktop = StreamerBotRoot;

        string fileName = "SD-Bridge-Installation-Report-" +
            DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture) + ".txt";
        string path = Path.Combine(desktop, fileName);

        StringBuilder report = new StringBuilder();
        report.AppendLine("SD Bridge installation / validation failure report");
        report.AppendLine("==================================================");
        report.AppendLine("Generated local: " + DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss zzz", CultureInfo.InvariantCulture));
        report.AppendLine("Generated UTC:   " + DateTime.UtcNow.ToString("yyyy-MM-dd HH:mm:ss 'UTC'", CultureInfo.InvariantCulture));
        report.AppendLine("Core version:     v0.20.0");
        report.AppendLine("Plugin UUID:      " + PluginUuid);
        report.AppendLine();
        report.AppendLine("This report is intended for SD Bridge community testing/support.");
        report.AppendLine("User-directory paths are sanitized. Review the file before posting it publicly.");
        report.AppendLine();

        report.AppendLine("[USER FEEDBACK]");
        if (symptoms != null && symptoms.Count > 0)
        {
            foreach (string symptom in symptoms)
                report.AppendLine("[x] " + symptom);
        }
        else
        {
            report.AppendLine("[ ] No checkbox selected");
        }
        report.AppendLine("Notes: " + (string.IsNullOrWhiteSpace(notes) ? "<none>" : SanitizeReportText(notes.Trim())));
        report.AppendLine();

        report.AppendLine("[ENVIRONMENT]");
        report.AppendLine("OS: " + Environment.OSVersion.VersionString);
        report.AppendLine("64-bit OS: " + Environment.Is64BitOperatingSystem.ToString());
        report.AppendLine("64-bit process: " + Environment.Is64BitProcess.ToString());
        report.AppendLine("Streamer.bot process version: " + GetCurrentProcessVersionForReport());
        report.AppendLine("Streamer.bot root: <STREAMERBOT_ROOT>");
        report.AppendLine("Stream Deck running: " + (Process.GetProcessesByName("StreamDeck").Length > 0 ? "yes" : "no"));

        string streamDeckExe = FindRunningStreamDeckExecutable();
        if (string.IsNullOrWhiteSpace(streamDeckExe) || !File.Exists(streamDeckExe))
            streamDeckExe = FindInstalledStreamDeckExecutable();
        report.AppendLine("Stream Deck executable: " + (string.IsNullOrWhiteSpace(streamDeckExe) ? "<not found>" : SanitizeReportText(streamDeckExe)));
        report.AppendLine("Stream Deck version: " + GetFileVersionForReport(streamDeckExe));
        report.AppendLine("Installed SD Bridge plugin version: " + GetInstalledPluginVersionForReport());
        string readinessIssue = string.Empty;
        bool companionReadyForReport = state != null && CompanionIsCurrent(state, out readinessIssue);
        report.AppendLine("Companion matching manifest/config/runtime: " + companionReadyForReport);
        if (!companionReadyForReport && state != null)
            report.AppendLine("Companion readiness reason: " + readinessIssue);
        report.AppendLine("Generated installer: " + (string.IsNullOrWhiteSpace(installer) ? "<none>" : Path.GetFileName(installer)));
        report.AppendLine("Full validation available: " + canFullValidate.ToString());
        report.AppendLine();

        report.AppendLine("[STATE]");
        report.AppendLine("Build: " + (state == null ? "0" : state.Build.ToString(CultureInfo.InvariantCulture)));
        report.AppendLine("Includes validation profile: " + (state != null && state.IncludesValidationProfile).ToString());
        report.AppendLine("Validation previously passed: " + (state != null && state.ValidationPassed).ToString());
        report.AppendLine("Configured profile count: " + ((state == null || state.Profiles == null) ? 0 : state.Profiles.Count).ToString(CultureInfo.InvariantCulture));
        report.AppendLine();

        report.AppendLine("[INSTALLATION CHECK]");
        if (installation == null || installation.Statuses == null || installation.Statuses.Count == 0)
        {
            report.AppendLine("<no installation status available>");
        }
        else
        {
            report.AppendLine("All ready: " + installation.AllReady.ToString());
            report.AppendLine("Has mismatch: " + installation.HasMismatch.ToString());
            foreach (ProfileInstallStatus item in installation.Statuses)
            {
                BridgeProfileState expected = item.Expected;
                string name = expected == null ? "<unknown>" : expected.BridgeName;
                int type = expected == null ? -1 : expected.DeviceType;
                int expectedPages = expected == null ? 0 : expected.ExpectedPageCount;
                int actualPages = item.Live == null || item.Live.Pages == null ? 0 : item.Live.Pages.Count;
                report.AppendLine("- " + name);
                report.AppendLine("  key=" + (expected == null ? "" : expected.Key));
                report.AppendLine("  deviceType=" + type.ToString(CultureInfo.InvariantCulture) + " (" + DeviceTypeName(type) + ")");
                report.AppendLine("  validationTest=" + (expected != null && expected.IsValidationTest).ToString());
                report.AppendLine("  detected=" + (item.Live != null ? "yes" : "no"));
                report.AppendLine("  expectedPages=" + expectedPages.ToString(CultureInfo.InvariantCulture) + ", actualPages=" + actualPages.ToString(CultureInfo.InvariantCulture));
                report.AppendLine("  status=" + item.Message);
                if (item.Live != null && item.Live.Pages != null)
                    report.AppendLine("  livePages=" + string.Join(" | ", item.Live.Pages.Select((p, i) => (i + 1).ToString(CultureInfo.InvariantCulture) + ":" + p)));
            }
        }
        report.AppendLine();

        report.AppendLine("[QUEUE]");
        try
        {
            string[] pending = Directory.Exists(CommandQueue)
                ? Directory.GetFiles(CommandQueue, "*.json")
                : new string[0];
            report.AppendLine("Pending command files: " + pending.Length.ToString(CultureInfo.InvariantCulture));
            if (pending.Length > 0)
            {
                DateTime oldest = pending.Select(File.GetLastWriteTimeUtc).Min();
                report.AppendLine("Oldest pending age seconds: " + Math.Max(0, (int)(DateTime.UtcNow - oldest).TotalSeconds).ToString(CultureInfo.InvariantCulture));
            }
        }
        catch (Exception ex)
        {
            report.AppendLine("Queue inspection failed: " + ex.Message);
        }
        report.AppendLine();

        report.AppendLine("[RUNTIME LOG TAIL — SANITIZED]");
        foreach (string line in GetSanitizedRuntimeLogTail(80))
            report.AppendLine(line);

        File.WriteAllText(path, report.ToString(), new UTF8Encoding(false));
        CPH.LogInfo("[SD Bridge] Validation failure report created: " + path);
        return path;
    }

    private string GetCurrentProcessVersionForReport()
    {
        try
        {
            using (Process process = Process.GetCurrentProcess())
            {
                if (process.MainModule != null && !string.IsNullOrWhiteSpace(process.MainModule.FileName))
                {
                    FileVersionInfo info = FileVersionInfo.GetVersionInfo(process.MainModule.FileName);
                    if (!string.IsNullOrWhiteSpace(info.ProductVersion))
                        return info.ProductVersion;
                    if (!string.IsNullOrWhiteSpace(info.FileVersion))
                        return info.FileVersion;
                }
            }
        }
        catch
        {
        }
        return "<unknown>";
    }

    private string GetFileVersionForReport(string path)
    {
        if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
            return "<not found>";
        try
        {
            FileVersionInfo info = FileVersionInfo.GetVersionInfo(path);
            if (!string.IsNullOrWhiteSpace(info.ProductVersion))
                return info.ProductVersion;
            if (!string.IsNullOrWhiteSpace(info.FileVersion))
                return info.FileVersion;
        }
        catch
        {
        }
        return "<unknown>";
    }

    private string GetInstalledPluginVersionForReport()
    {
        try
        {
            string manifestPath = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                "Elgato", "StreamDeck", "Plugins", PluginUuid + ".sdPlugin", "manifest.json");
            if (!File.Exists(manifestPath))
                return "<not installed>";
            JObject manifest = JObject.Parse(File.ReadAllText(manifestPath, Encoding.UTF8));
            return (string)manifest["Version"] ?? "<unknown>";
        }
        catch (Exception ex)
        {
            return "<read error: " + ex.Message + ">";
        }
    }

    private IEnumerable<string> GetSanitizedRuntimeLogTail(int maxLines)
    {
        List<string> result = new List<string>();
        try
        {
            string logPath = Path.Combine(
                Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                "Elgato", "StreamDeck", "Plugins", PluginUuid + ".sdPlugin",
                "logs", "sd-bridge.log");
            if (!File.Exists(logPath))
            {
                result.Add("<runtime log not found>");
                return result;
            }

            string[] lines = File.ReadAllLines(logPath, Encoding.UTF8);
            int start = Math.Max(0, lines.Length - Math.Max(1, maxLines));
            for (int i = start; i < lines.Length; i++)
                result.Add(SanitizeReportText(SanitizeDeviceIdsInLogLine(lines[i])));
        }
        catch (Exception ex)
        {
            result.Add("<runtime log read error: " + ex.Message + ">");
        }
        return result;
    }

    private string SanitizeDeviceIdsInLogLine(string line)
    {
        string value = line ?? "";

        int connected = value.IndexOf("Device connected ", StringComparison.OrdinalIgnoreCase);
        if (connected >= 0)
        {
            int start = connected + "Device connected ".Length;
            int end = value.IndexOf(" type=", start, StringComparison.OrdinalIgnoreCase);
            if (end > start)
                value = value.Substring(0, start) + "<device-id>" + value.Substring(end);
        }

        int device = value.IndexOf(" device=", StringComparison.OrdinalIgnoreCase);
        if (device >= 0)
        {
            int start = device + " device=".Length;
            int end = value.IndexOf(' ', start);
            if (end < 0)
                end = value.Length;
            value = value.Substring(0, start) + "<device-id>" + value.Substring(end);
        }

        return value;
    }

    private string SanitizeReportText(string value)
    {
        if (string.IsNullOrEmpty(value))
            return value ?? "";

        string sanitized = value;
        string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
        string localAppData = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
        string userProfile = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
        string desktop = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);

        if (!string.IsNullOrWhiteSpace(StreamerBotRoot))
            sanitized = ReplaceIgnoreCase(sanitized, StreamerBotRoot, "<STREAMERBOT_ROOT>");
        if (!string.IsNullOrWhiteSpace(desktop))
            sanitized = ReplaceIgnoreCase(sanitized, desktop, "<DESKTOP>");
        if (!string.IsNullOrWhiteSpace(appData))
            sanitized = ReplaceIgnoreCase(sanitized, appData, "%APPDATA%");
        if (!string.IsNullOrWhiteSpace(localAppData))
            sanitized = ReplaceIgnoreCase(sanitized, localAppData, "%LOCALAPPDATA%");
        if (!string.IsNullOrWhiteSpace(userProfile))
            sanitized = ReplaceIgnoreCase(sanitized, userProfile, "%USERPROFILE%");

        return sanitized;
    }

    private string ReplaceIgnoreCase(string input, string oldValue, string newValue)
    {
        if (string.IsNullOrEmpty(input) || string.IsNullOrEmpty(oldValue))
            return input;

        StringBuilder result = new StringBuilder();
        int start = 0;
        while (true)
        {
            int index = input.IndexOf(oldValue, start, StringComparison.OrdinalIgnoreCase);
            if (index < 0)
            {
                result.Append(input.Substring(start));
                break;
            }
            result.Append(input.Substring(start, index - start));
            result.Append(newValue);
            start = index + oldValue.Length;
        }
        return result.ToString();
    }

    private void RevealFileInExplorer(string path)
    {
        try
        {
            if (string.IsNullOrWhiteSpace(path) || !File.Exists(path))
                return;
            ProcessStartInfo psi = new ProcessStartInfo("explorer.exe", "/select,\"" + path + "\"");
            psi.UseShellExecute = true;
            Process.Start(psi);
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not reveal report in Explorer: " + ex.Message);
        }
    }

    private bool ShowEnglishConfirm(
        Window owner,
        string title,
        string message,
        string confirmText,
        string cancelText)
    {
        bool accepted = false;
        Window dialog = CreateWindow(title, 560, 300);
        dialog.ResizeMode = ResizeMode.NoResize;
        try
        {
            dialog.Owner = owner;
            dialog.WindowStartupLocation = WindowStartupLocation.CenterOwner;
        }
        catch
        {
            dialog.WindowStartupLocation = WindowStartupLocation.CenterScreen;
        }

        Grid root = new Grid { Margin = new Thickness(18) };
        root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        SetWindowContent(dialog, root);

        StackPanel body = new StackPanel { VerticalAlignment = VerticalAlignment.Center };
        body.Children.Add(new TextBlock
        {
            Text = title,
            FontSize = 16,
            FontWeight = FontWeights.SemiBold,
            Foreground = Brushes.White,
            Margin = new Thickness(0, 0, 0, 10)
        });
        body.Children.Add(new TextBlock
        {
            Text = message,
            Foreground = ThemeMuted(),
            FontSize = 12,
            TextWrapping = TextWrapping.Wrap
        });
        Grid.SetRow(body, 0);
        root.Children.Add(body);

        StackPanel buttons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Right,
            Margin = new Thickness(0, 18, 0, 0)
        };
        Button cancel = MakeButton(cancelText, 110, "secondary");
        Button confirm = MakeButton(confirmText, 130, "primary");
        buttons.Children.Add(cancel);
        buttons.Children.Add(confirm);
        Grid.SetRow(buttons, 1);
        root.Children.Add(buttons);

        cancel.Click += delegate { dialog.Close(); };
        confirm.Click += delegate
        {
            accepted = true;
            dialog.Close();
        };

        dialog.ShowDialog();
        return accepted;
    }

    // -------------------------------------------------------------------------
    // PAGE PICKER WPF
    // -------------------------------------------------------------------------

    private bool ShowPagePickerWindow()
    {
        BridgeState state = LoadState();
        List<BridgeProfileState> configured = GetSwitchableProfiles(state);
        if (configured.Count == 0)
        {
            MessageBox.Show("No Bridge profile is configured. Run SetupBridge first.", PluginName,
                MessageBoxButton.OK, MessageBoxImage.Information);
            return false;
        }

        List<Tuple<BridgeProfileState, ProfileInfo>> available =
            new List<Tuple<BridgeProfileState, ProfileInfo>>();

        foreach (BridgeProfileState p in configured)
        {
            ProfileInfo live = FindLiveBridgeProfile(p);
            if (live != null)
                available.Add(Tuple.Create(p, live));
        }

        if (available.Count == 0)
        {
            MessageBox.Show("The configured [Bridge] profiles are not installed yet. " +
                "Install/update the generated Stream Deck plugin first.", PluginName,
                MessageBoxButton.OK, MessageBoxImage.Warning);
            return false;
        }

        Window window = CreateWindow("SD Bridge — Switch Page", 520, 320);
        Grid root = new Grid { Margin = new Thickness(18) };
        for (int i = 0; i < 5; i++)
            root.RowDefinitions.Add(new RowDefinition { Height = GridLength.Auto });
        root.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        SetWindowContent(window, root);

        TextBlock intro = new TextBlock
        {
            Text = "Select the current bridged profile and page. In Streamer.bot, sdBridge.page accepts either the page name or its 1-based number.",
            Foreground = Brushes.White,
            FontSize = 15,
            TextWrapping = TextWrapping.Wrap,
            Margin = new Thickness(0, 0, 0, 14)
        };
        Grid.SetRow(intro, 0);
        root.Children.Add(intro);

        TextBlock profileLabel = LabelText("Profile");
        Grid.SetRow(profileLabel, 1);
        root.Children.Add(profileLabel);

        ComboBox profileCombo = new ComboBox { Margin = new Thickness(0, 4, 0, 12), MinHeight = 30 };
        foreach (Tuple<BridgeProfileState, ProfileInfo> x in available)
            profileCombo.Items.Add(x.Item2.Name);
        profileCombo.SelectedIndex = 0;
        Grid.SetRow(profileCombo, 2);
        root.Children.Add(profileCombo);

        TextBlock pageLabel = LabelText("Page");
        Grid.SetRow(pageLabel, 3);
        root.Children.Add(pageLabel);

        ComboBox pageCombo = new ComboBox { Margin = new Thickness(0, 4, 0, 12), MinHeight = 30 };
        Grid.SetRow(pageCombo, 4);
        root.Children.Add(pageCombo);

        Action refillPages = delegate
        {
            pageCombo.Items.Clear();
            int idx = Math.Max(0, profileCombo.SelectedIndex);
            ProfileInfo live = available[idx].Item2;
            for (int i = 0; i < live.Pages.Count; i++)
                pageCombo.Items.Add((i + 1).ToString(CultureInfo.InvariantCulture) + " — " + live.Pages[i]);
            if (pageCombo.Items.Count > 0)
                pageCombo.SelectedIndex = 0;
        };

        profileCombo.SelectionChanged += delegate { refillPages(); };
        refillPages();

        StackPanel buttons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Right,
            Margin = new Thickness(0, 8, 0, 0)
        };
        Button go = MakeButton("Switch", 100);
        Button cancel = MakeButton("Cancel", 90);
        buttons.Children.Add(go);
        buttons.Children.Add(cancel);
        Grid.SetRow(buttons, 5);
        root.Children.Add(buttons);

        bool sent = false;
        go.Click += delegate
        {
            int pIdx = Math.Max(0, profileCombo.SelectedIndex);
            int pageIdx = Math.Max(0, pageCombo.SelectedIndex);
            if (pageCombo.Items.Count == 0)
                return;

            BridgeProfileState target = available[pIdx].Item1;
            ProfileInfo live = available[pIdx].Item2;
            sent = QueueSwitch(target, pageIdx + 1, live.Pages[pageIdx], live.Pages.Count);
            if (sent)
                window.Close();
        };
        cancel.Click += delegate { window.Close(); };

        window.ShowDialog();
        return sent;
    }

    // -------------------------------------------------------------------------
    // SWITCH / ARGUMENTS
    // -------------------------------------------------------------------------

    private object GetPageArgument()
    {
        // Read as text first. Streamer.bot's TryGetArg<int>() may throw a
        // FormatException when the argument contains a page name such as
        // "Page 1" instead of simply returning false.
        string pageText = null;

        try
        {
            if (CPH.TryGetArg<string>(ArgPage, out pageText) &&
                !string.IsNullOrWhiteSpace(pageText))
            {
                pageText = pageText.Trim();

                int parsed;
                if (int.TryParse(pageText, NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed))
                    return parsed;

                return pageText;
            }
        }
        catch
        {
            // Fall through to alternate argument / typed integer fallback.
        }

        try
        {
            if (CPH.TryGetArg<string>("page", out pageText) &&
                !string.IsNullOrWhiteSpace(pageText))
            {
                pageText = pageText.Trim();

                int parsed;
                if (int.TryParse(pageText, NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed))
                    return parsed;

                return pageText;
            }
        }
        catch
        {
            // Fall through to typed integer fallback.
        }

        int pageInt;

        try
        {
            if (CPH.TryGetArg<int>(ArgPage, out pageInt))
                return pageInt;
        }
        catch
        {
        }

        try
        {
            if (CPH.TryGetArg<int>("page", out pageInt))
                return pageInt;
        }
        catch
        {
        }

        return null;
    }

    private string GetStringArg(string name)
    {
        string value;
        if (CPH.TryGetArg<string>(name, out value))
            return value;
        return null;
    }

    private bool ResolvePage(ProfileInfo live, object pageArg, out int pageNumber, out string pageLabel)
    {
        pageNumber = 0;
        pageLabel = null;
        if (pageArg == null)
            return false;

        if (pageArg is int)
        {
            pageNumber = (int)pageArg;
        }
        else
        {
            string s = Convert.ToString(pageArg, CultureInfo.InvariantCulture);
            int parsed;
            if (int.TryParse(s, NumberStyles.Integer, CultureInfo.InvariantCulture, out parsed))
            {
                pageNumber = parsed;
            }
            else
            {
                List<int> matches = new List<int>();
                for (int i = 0; i < live.Pages.Count; i++)
                {
                    if (string.Equals(live.Pages[i], s, StringComparison.OrdinalIgnoreCase))
                        matches.Add(i);
                }

                if (matches.Count != 1)
                    return false;

                pageNumber = matches[0] + 1;
            }
        }

        if (pageNumber < 1 || pageNumber > live.Pages.Count)
            return false;

        pageLabel = live.Pages[pageNumber - 1];
        return true;
    }

    private bool QueueSwitch(BridgeProfileState target, int pageNumber, string pageLabel, int pageCount)
    {
        string commandPath;
        return QueueSwitchInternal(target, pageNumber, pageLabel, pageCount, out commandPath);
    }

    private bool QueueSwitchInternal(BridgeProfileState target, int pageNumber, string pageLabel, int pageCount, out string commandPath)
    {
        commandPath = null;
        try
        {
            Directory.CreateDirectory(CommandQueue);

            JObject cmd = new JObject();
            cmd["requestId"] = Guid.NewGuid().ToString("N");
            cmd["profileKey"] = target.Key;
            cmd["profile"] = target.BridgeName;
            cmd["page"] = pageNumber;
            cmd["pageName"] = pageLabel ?? "";
            cmd["createdUtc"] = DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture);

            string id = DateTime.UtcNow.Ticks.ToString("D19", CultureInfo.InvariantCulture) + "-" +
                        Guid.NewGuid().ToString("N");
            string tmp = Path.Combine(CommandQueue, id + ".tmp");
            string final = Path.Combine(CommandQueue, id + ".json");

            File.WriteAllText(tmp, cmd.ToString(Formatting.None), new UTF8Encoding(false));
            File.Move(tmp, final);
            commandPath = final;

            CPH.SetArgument("sdBridge.resolvedProfile", target.BridgeName);
            CPH.SetArgument("sdBridge.resolvedPage", pageNumber);
            CPH.SetArgument("sdBridge.resolvedPageName", pageLabel ?? "");
            CPH.SetArgument("sdBridge.pageCount", pageCount);

            CPH.LogInfo("[SD Bridge] Switch queued => " + target.BridgeName + " / " +
                pageNumber + "/" + pageCount + " / " + (pageLabel ?? ""));
            return true;
        }
        catch (Exception ex)
        {
            CPH.LogError("[SD Bridge] Failed to queue switch: " + ex);
            return false;
        }
    }

    // -------------------------------------------------------------------------
    // PROFILE DISCOVERY
    // -------------------------------------------------------------------------

    private List<ProfileInfo> ScanProfiles()
    {
        List<ProfileInfo> result = new List<ProfileInfo>();
        string streamDeckRoot = Path.Combine(
            Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
            "Elgato", "StreamDeck");

        string[] stores = new[]
        {
            Path.Combine(streamDeckRoot, "ProfilesV3"),
            Path.Combine(streamDeckRoot, "ProfilesV2")
        };

        foreach (string store in stores)
        {
            if (!Directory.Exists(store))
                continue;

            string storeVersion = Path.GetFileName(store);
            foreach (string dir in Directory.GetDirectories(store, "*.sdProfile"))
            {
                try
                {
                    string manifestPath = Path.Combine(dir, "manifest.json");
                    if (!File.Exists(manifestPath))
                        continue;

                    JObject manifest = JObject.Parse(File.ReadAllText(manifestPath, Encoding.UTF8));
                    string name = (string)manifest["Name"];
                    if (string.IsNullOrWhiteSpace(name))
                        name = Path.GetFileNameWithoutExtension(dir);

                    string model = "";
                    JObject device = manifest["Device"] as JObject;
                    if (device != null)
                        model = (string)device["Model"] ?? "";

                    List<string> pages = ReadPageNames(dir, manifest);
                    int deviceType = InferDeviceType(model, dir, manifest);

                    bool isManagedBridge = false;
                    string bridgeKey = "";
                    string bridgeSourceName = "";
                    int bridgeMarkerVersion = 0;
                    string markerPath = Path.Combine(dir, BridgeMarkerFileName);
                    if (File.Exists(markerPath))
                    {
                        try
                        {
                            JObject marker = JObject.Parse(File.ReadAllText(markerPath, Encoding.UTF8));
                            string markerPlugin = (string)marker["pluginUuid"] ?? "";
                            bridgeKey = (string)marker["bridgeKey"] ?? "";
                            bridgeSourceName = (string)marker["sourceName"] ?? "";
                            bridgeMarkerVersion = (int?)marker["version"] ?? 0;
                            isManagedBridge =
                                string.Equals(markerPlugin, PluginUuid, StringComparison.OrdinalIgnoreCase) &&
                                !string.IsNullOrWhiteSpace(bridgeKey);
                        }
                        catch (Exception markerEx)
                        {
                            CPH.LogWarn("[SD Bridge] Invalid bridge marker in " + dir + ": " + markerEx.Message);
                        }
                    }

                    ProfileInfo info = new ProfileInfo();
                    info.SourcePath = dir;
                    info.Id = Path.GetFileNameWithoutExtension(dir);
                    info.Name = name;
                    info.Model = model;
                    info.DeviceType = deviceType;
                    info.Pages = pages;
                    info.StoreVersion = storeVersion;
                    info.LastWriteUtc = Directory.GetLastWriteTimeUtc(dir);
                    info.IsManagedBridge = isManagedBridge;
                    info.BridgeKey = bridgeKey;
                    info.BridgeSourceName = bridgeSourceName;
                    info.BridgeMarkerVersion = bridgeMarkerVersion;
                    result.Add(info);
                }
                catch (Exception ex)
                {
                    CPH.LogWarn("[SD Bridge] Could not read profile " + dir + ": " + ex.Message);
                }
            }
        }

        return result;
    }

    private List<string> ReadPageNames(string profileDir, JObject manifest)
    {
        List<string> names = new List<string>();
        JObject pages = manifest["Pages"] as JObject;
        JArray pageIds = pages == null ? null : pages["Pages"] as JArray;

        if (pageIds == null || pageIds.Count == 0)
        {
            names.Add((string)manifest["Name"] ?? "Page 1");
            return names;
        }

        for (int i = 0; i < pageIds.Count; i++)
        {
            string id = Convert.ToString(pageIds[i], CultureInfo.InvariantCulture);
            string pageManifest = FindPageManifest(profileDir, id);
            string pageName = "";

            if (pageManifest != null)
            {
                try
                {
                    JObject p = JObject.Parse(File.ReadAllText(pageManifest, Encoding.UTF8));
                    pageName = (string)p["Name"] ?? "";
                }
                catch { }
            }

            if (string.IsNullOrWhiteSpace(pageName))
                pageName = "Page " + (i + 1).ToString(CultureInfo.InvariantCulture);

            names.Add(pageName);
        }

        return names;
    }

    private string FindPageManifest(string profileDir, string pageUuid)
    {
        string profilesDir = Path.Combine(profileDir, "Profiles");
        if (!Directory.Exists(profilesDir))
            return null;

        string raw = Path.Combine(profilesDir, pageUuid, "manifest.json");
        if (File.Exists(raw))
            return raw;

        string encoded = Path.Combine(profilesDir, EncodeV2PageFolder(pageUuid), "manifest.json");
        if (File.Exists(encoded))
            return encoded;

        return null;
    }

    private string EncodeV2PageFolder(string uuid)
    {
        string hex = (uuid ?? "").Replace("-", "").ToLowerInvariant() + "000";
        StringBuilder output = new StringBuilder();

        for (int i = 0; i + 5 <= hex.Length; i += 5)
        {
            int value = Convert.ToInt32(hex.Substring(i, 5), 16);
            output.Append(ToBase32(value).PadLeft(4, '0'));
        }

        string s = output.ToString();
        if (s.Length > 26)
            s = s.Substring(0, 26);

        return s.ToUpperInvariant().Replace("V", "W").Replace("U", "V") + "Z";
    }

    private string ToBase32(int value)
    {
        const string chars = "0123456789abcdefghijklmnopqrstuv";
        if (value == 0)
            return "0";

        StringBuilder s = new StringBuilder();
        while (value > 0)
        {
            s.Insert(0, chars[value % 32]);
            value /= 32;
        }
        return s.ToString();
    }

    private int InferDeviceType(string model, string profileDir, JObject manifest)
    {
        // Prefer an explicit DeviceType when Stream Deck stores one in the local profile.
        // This is especially important for software/virtual devices whose grid geometry can
        // intentionally mimic another physical Stream Deck.
        try
        {
            JObject explicitDevice = manifest == null ? null : manifest["Device"] as JObject;
            JToken explicitToken = explicitDevice == null ? null : explicitDevice["Type"];
            if (explicitToken == null && manifest != null)
                explicitToken = manifest["DeviceType"];

            int explicitType;
            if (explicitToken != null &&
                int.TryParse(Convert.ToString(explicitToken, CultureInfo.InvariantCulture), out explicitType) &&
                IsBridgeableDeviceType(explicitType))
            {
                return explicitType;
            }
        }
        catch
        {
        }

        string m = (model ?? "").Trim().ToUpperInvariant();

        // Human-readable identifiers, useful for Mobile / Virtual / integrated devices.
        if (m.Contains("VIRTUAL"))
            return 11;
        if (m.Contains("MOBILE"))
            return 3;
        if (m.Contains("GALLEON"))
            return 12;
        if (m.Contains("STUDIO"))
            return 10;
        if (m.Contains("SCUF"))
            return 8;
        if (m.Contains("VOYAGER"))
            return 6;
        if (m.Contains("PEDAL"))
            return 5;
        if (m.Contains("NEO"))
            return 9;

        // Known Elgato hardware model identifiers observed in local Stream Deck profiles.
        if (m == "20GAT9901" || m == "20GAT9902")
            return 2; // XL
        if (m == "20GAI9901" || m == "20GAI9902" || m == "20GAI9501" || m == "20GAM9901")
            return 1; // Mini
        if (m == "20GBJ9901")
            return 9; // Neo
        if (m == "20GAA9901" || m == "20GAA9902" || m == "20GBA9901" || m == "20GBL9901")
            return 0; // classic / MK.2
        if (m == "20GAQ9901")
            return 5; // Pedal
        if (m == "20GBD9901")
            return 7; // Stream Deck +
        if (m == "20GBX9901")
            return 13; // Stream Deck + XL

        // Geometry fallback. It is intentionally secondary to an explicit DeviceType/model.
        // Modern devices have distinct key-grid shapes:
        // Studio 16x2, + XL 9x4, XL 8x4, Galleon 6x2 + encoders,
        // classic 5x3, + / Neo 4x2, Mini 3x2.
        int maxX = -1;
        int maxY = -1;
        bool hasEncoder = false;

        JObject pages = manifest == null ? null : manifest["Pages"] as JObject;
        JArray pageIds = pages == null ? null : pages["Pages"] as JArray;
        if (pageIds != null)
        {
            foreach (JToken token in pageIds)
            {
                string pm = FindPageManifest(profileDir, Convert.ToString(token, CultureInfo.InvariantCulture));
                if (pm == null)
                    continue;

                try
                {
                    JObject p = JObject.Parse(File.ReadAllText(pm, Encoding.UTF8));
                    JArray controllers = p["Controllers"] as JArray;
                    if (controllers == null)
                        continue;

                    foreach (JObject controller in controllers.OfType<JObject>())
                    {
                        string type = (string)controller["Type"] ?? "";
                        if (string.Equals(type, "Encoder", StringComparison.OrdinalIgnoreCase))
                            hasEncoder = true;

                        JObject actions = controller["Actions"] as JObject;
                        if (actions == null)
                            continue;

                        foreach (JProperty prop in actions.Properties())
                        {
                            string[] parts = prop.Name.Split(',');
                            int x, y;
                            if (parts.Length == 2 &&
                                int.TryParse(parts[0], out x) &&
                                int.TryParse(parts[1], out y))
                            {
                                maxX = Math.Max(maxX, x);
                                maxY = Math.Max(maxY, y);
                            }
                        }
                    }
                }
                catch
                {
                }
            }
        }

        if (maxX >= 15 && maxY >= 1)
            return 10; // Stream Deck Studio: 16x2 key surface
        if (maxX >= 8 && maxY >= 3)
            return hasEncoder ? 13 : 2; // + XL 9x4, or unknown 9x4 keypad fallback
        if (maxX >= 7 && maxY >= 3)
            return 2; // XL 8x4
        if (maxX >= 5 && maxY >= 1 && hasEncoder)
            return 12; // Galleon 100 SD: 6x2 + dials
        if (maxX >= 4 && maxY >= 2)
            return 0; // classic / MK.2 5x3
        if (maxX >= 3 && maxY >= 1)
            return hasEncoder ? 7 : 9; // Stream Deck + / Neo
        if (maxX >= 2 && maxY >= 1)
            return 1; // Mini 3x2

        return -1;
    }

    private ProfileInfo FindLiveBridgeProfile(BridgeProfileState target)
    {
        if (target == null)
            return null;

        // The temporary Bridge Validation Test is also a plugin-owned profile
        // and is intentionally switchable while it is installed.
        return FindLiveProfileForState(target);
    }

    private ProfileInfo FindLiveProfileForState(BridgeProfileState target)
    {
        return FindLiveProfileForState(target, ScanProfiles());
    }

    private ProfileInfo FindLiveProfileForState(BridgeProfileState target, List<ProfileInfo> profiles)
    {
        if (target == null)
            return null;

        List<ProfileInfo> supported = (profiles ?? new List<ProfileInfo>())
            .Where(p => IsBridgeableDeviceType(p.DeviceType))
            .OrderByDescending(p =>
                IsBridgeableDeviceType(target.DeviceType) && p.DeviceType == target.DeviceType)
            .ThenByDescending(p => p.LastWriteUtc)
            .ToList();

        // Stable Bridge identity: the marker is stored inside the editable Bridge profile itself.
        // This survives profile renames and prevents a previously bridged profile from ever
        // being interpreted as a fresh source merely because its display name changed.
        if (!string.IsNullOrWhiteSpace(target.Key))
        {
            ProfileInfo byMarker = supported.FirstOrDefault(p =>
                p.IsManagedBridge &&
                string.Equals(p.BridgeKey, target.Key, StringComparison.OrdinalIgnoreCase));
            if (byMarker != null)
                return byMarker;
        }

        // Once observed locally, the Stream Deck profile directory id is a useful second identity.
        if (!string.IsNullOrWhiteSpace(target.BridgeId))
        {
            ProfileInfo byId = supported.FirstOrDefault(p =>
                string.Equals(p.Id, target.BridgeId, StringComparison.OrdinalIgnoreCase));
            if (byId != null)
                return byId;
        }

        // Legacy V10 and earlier fallback.
        ProfileInfo byName = supported.FirstOrDefault(p =>
            string.Equals(p.Name, target.BridgeName, StringComparison.OrdinalIgnoreCase));
        if (byName != null)
            return byName;

        return null;
    }

    // -------------------------------------------------------------------------
    // PLUGIN GENERATOR
    // -------------------------------------------------------------------------

    private string BuildBridgePlugin(List<ProfileInfo> selected, bool includeValidationProfile)
    {
        Directory.CreateDirectory(PortableDataRoot);

        BridgeState oldState = LoadState();
        int stateBuild = oldState == null ? 0 : Math.Max(0, oldState.Build);
        int build = GetNextCompanionBuild(stateBuild);

        foreach (ProfileInfo p in selected ?? new List<ProfileInfo>())
        {
            if (!IsBridgeableDeviceType(p.DeviceType))
                throw new InvalidOperationException(
                    "Unknown or unsupported Stream Deck DeviceType for profile '" + p.Name +
                    "': " + p.DeviceType.ToString(CultureInfo.InvariantCulture));
        }

        string tempRoot = Path.Combine(Path.GetTempPath(), "sd-bridge-build-" + Guid.NewGuid().ToString("N"));
        string pluginDir = Path.Combine(tempRoot, PluginUuid + ".sdPlugin");
        Directory.CreateDirectory(pluginDir);
        Directory.CreateDirectory(Path.Combine(pluginDir, "bin"));
        Directory.CreateDirectory(Path.Combine(pluginDir, "profiles"));
        Directory.CreateDirectory(Path.Combine(pluginDir, "imgs", "plugin"));
        Directory.CreateDirectory(Path.Combine(pluginDir, "imgs", "actions", "bridge"));

        File.WriteAllBytes(Path.Combine(pluginDir, "bin", "plugin.js"), Convert.FromBase64String(PluginJsBase64));
        File.WriteAllText(Path.Combine(pluginDir, "bin", "package.json"),
            "{\"name\":\"sd-bridge\",\"type\":\"module\"}", new UTF8Encoding(false));
        File.WriteAllBytes(Path.Combine(pluginDir, "imgs", "plugin", "icon.png"), Convert.FromBase64String(PluginIconBase64));
        File.WriteAllBytes(Path.Combine(pluginDir, "imgs", "actions", "bridge", "icon.png"), Convert.FromBase64String(ActionIconBase64));
        File.WriteAllBytes(Path.Combine(pluginDir, "imgs", "actions", "bridge", "key.png"), Convert.FromBase64String(ActionIconBase64));

        HashSet<string> usedKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        List<BridgeProfileState> bridgeProfiles = new List<BridgeProfileState>();
        List<BridgeProfileState> installedConfig = LoadInstalledBridgeConfigProfiles();

        foreach (BridgeProfileState old in GetConfiguredProfiles(oldState))
        {
            ProfileInfo live = FindLiveProfileForState(old);
            if (live == null || !IsBridgeableDeviceType(live.DeviceType))
                continue;

            string key;
            if (!string.IsNullOrWhiteSpace(old.Key))
            {
                key = old.Key;
                if (usedKeys.Contains(key))
                    throw new InvalidOperationException(
                        "Duplicate stable Bridge key '" + key + "' detected. Run Clean / Rebuild state before generating the plugin; SD Bridge will not silently rename an existing identity.");
            }
            else
            {
                key = UniqueKey(MakeKey(old.SourceName), usedKeys);
            }
            usedKeys.Add(key);

            string sourceName = !string.IsNullOrWhiteSpace(old.SourceName)
                ? old.SourceName
                : (!string.IsNullOrWhiteSpace(live.BridgeSourceName) ? live.BridgeSourceName : StripBridgeSuffix(live.Name));
            string bridgeDisplayName = HasRepeatedBridgeSuffix(live.Name) ? NormalizeBridgeName(live.Name) : live.Name;
            string packagePath = Path.Combine(pluginDir, "profiles", key + ".streamDeckProfile");
            CreateStreamDeckProfilePackage(live.SourcePath, packagePath, bridgeDisplayName, key, sourceName);

            BridgeProfileState b = new BridgeProfileState();
            b.Key = key;
            b.SourceName = sourceName;
            b.SourcePath = old.SourcePath;
            b.SourceId = old.SourceId;
            b.BridgeId = live.Id;
            b.BridgeName = bridgeDisplayName;
            b.SdkProfile = "profiles/" + key;
            b.DeviceType = live.DeviceType;
            b.ExpectedPageCount = live.Pages.Count;
            b.ExpectedPages = new List<string>(live.Pages);
            b.IsValidationTest = false;
            BridgeProfileState installed = installedConfig.FirstOrDefault(x =>
                string.Equals(x.Key, key, StringComparison.OrdinalIgnoreCase));
            b.Aliases = BuildCompactedAliases(b, old, installed);
            bridgeProfiles.Add(b);
        }

        foreach (ProfileInfo source in selected ?? new List<ProfileInfo>())
        {
            if (source.IsManagedBridge)
                continue;

            bool alreadyRepresented = bridgeProfiles.Any(x =>
                (!string.IsNullOrWhiteSpace(x.SourceId) && !string.IsNullOrWhiteSpace(source.Id) &&
                 string.Equals(x.SourceId, source.Id, StringComparison.OrdinalIgnoreCase)) ||
                (string.IsNullOrWhiteSpace(x.SourceId) &&
                 string.Equals(x.SourceName, source.Name, StringComparison.OrdinalIgnoreCase) &&
                 x.DeviceType == source.DeviceType));
            if (alreadyRepresented)
                continue;

            string key = UniqueKey(MakeKey(source.Name), usedKeys);
            usedKeys.Add(key);
            string bridgeName = NormalizeBridgeName(source.Name);
            string packagePath = Path.Combine(pluginDir, "profiles", key + ".streamDeckProfile");
            CreateStreamDeckProfilePackage(source.SourcePath, packagePath, bridgeName, key, source.Name);

            BridgeProfileState b = new BridgeProfileState();
            b.Key = key;
            b.SourceName = source.Name;
            b.SourcePath = source.SourcePath;
            b.SourceId = source.Id;
            b.BridgeId = "";
            b.BridgeName = bridgeName;
            b.SdkProfile = "profiles/" + key;
            b.DeviceType = source.DeviceType;
            b.ExpectedPageCount = source.Pages.Count;
            b.ExpectedPages = new List<string>(source.Pages);
            b.Aliases = new List<string>();
            b.IsValidationTest = false;
            bridgeProfiles.Add(b);
        }

        if (includeValidationProfile)
        {
            if (usedKeys.Contains(ValidationProfileKey))
                throw new InvalidOperationException("The reserved validation profile key conflicts with an existing Bridge key.");
            string packagePath = Path.Combine(pluginDir, "profiles", ValidationProfileKey + ".streamDeckProfile");
            CreateEmbeddedValidationProfilePackage(packagePath);
            BridgeProfileState test = new BridgeProfileState();
            test.Key = ValidationProfileKey;
            test.SourceName = ValidationProfileName;
            test.SourcePath = "";
            test.SourceId = "";
            test.BridgeId = "";
            test.BridgeName = ValidationProfileDisplayName;
            test.SdkProfile = ValidationProfileSdk;
            test.DeviceType = ValidationDeviceType;
            test.ExpectedPageCount = ValidationProfilePageCount;
            test.ExpectedPages = Enumerable.Range(1, ValidationProfilePageCount)
                .Select(i => "Page " + i.ToString(CultureInfo.InvariantCulture)).ToList();
            test.Aliases = new List<string>();
            test.IsValidationTest = true;
            bridgeProfiles.Add(test);
        }

        if (bridgeProfiles.Count == 0)
            throw new InvalidOperationException("There is no bridged profile to package.");

        JObject bridgeConfig = new JObject();
        bridgeConfig["version"] = 5;
        JArray cfgProfiles = new JArray();
        foreach (BridgeProfileState b in bridgeProfiles)
        {
            JObject p = new JObject();
            p["key"] = b.Key;
            p["sourceName"] = b.SourceName;
            p["bridgeId"] = b.BridgeId ?? "";
            p["displayName"] = b.BridgeName;
            p["sdkProfile"] = b.SdkProfile;
            p["deviceType"] = b.DeviceType;
            p["aliases"] = new JArray((b.Aliases ?? new List<string>())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase));
            p["isValidationTest"] = b.IsValidationTest;
            cfgProfiles.Add(p);
        }
        bridgeConfig["profiles"] = cfgProfiles;
        File.WriteAllText(Path.Combine(pluginDir, "bridge-config.json"),
            bridgeConfig.ToString(Formatting.Indented), new UTF8Encoding(false));

        JObject manifest = new JObject();
        manifest["$schema"] = "https://schemas.elgato.com/streamdeck/plugins/manifest.json";
        manifest["UUID"] = PluginUuid;
        manifest["Name"] = PluginName;
        manifest["Version"] = "1.20.0." + build.ToString(CultureInfo.InvariantCulture);
        manifest["Author"] = "LeBlux";
        manifest["Description"] =
            "Lets Streamer.bot switch Stream Deck profiles and pages through editable Bridge profiles. Companion addon; does not replace the official Streamer.bot plugin.";

        JArray actions = new JArray();
        JObject action = new JObject();
        action["Name"] = "Bridge Runtime";
        action["UUID"] = PluginUuid + ".bridge";
        action["Tooltip"] = "Internal SD Bridge runtime";
        action["Icon"] = "imgs/actions/bridge/icon";
        action["Controllers"] = new JArray { "Keypad" };
        action["VisibleInActionsList"] = false;
        action["States"] = new JArray(new JObject(new JProperty("Image", "imgs/actions/bridge/key")));
        actions.Add(action);
        manifest["Actions"] = actions;
        manifest["CodePath"] = "bin/plugin.js";
        manifest["Icon"] = "imgs/plugin/icon";
        manifest["SDKVersion"] = 2;
        manifest["Software"] = new JObject(new JProperty("MinimumVersion", "6.6"));
        manifest["OS"] = new JArray(new JObject(
            new JProperty("Platform", "windows"),
            new JProperty("MinimumVersion", "10")));
        manifest["Nodejs"] = new JObject(new JProperty("Version", "20"));

        JArray profilesManifest = new JArray();
        foreach (BridgeProfileState b in bridgeProfiles)
        {
            JObject p = new JObject();
            p["Name"] = b.SdkProfile;
            p["DeviceType"] = b.DeviceType;
            p["Readonly"] = false;
            p["DontAutoSwitchWhenInstalled"] = true;
            p["AutoInstall"] = true;
            profilesManifest.Add(p);
        }
        manifest["Profiles"] = profilesManifest;
        File.WriteAllText(Path.Combine(pluginDir, "manifest.json"),
            manifest.ToString(Formatting.Indented), new UTF8Encoding(false));

        string desktop = Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory);
        string outputDir = Path.Combine(desktop, "SD Bridge");
        Directory.CreateDirectory(outputDir);
        string installer = Path.Combine(outputDir, "SD-Bridge.streamDeckPlugin");
        string staging = Path.Combine(outputDir, "SD-Bridge-" + Guid.NewGuid().ToString("N") + ".tmp");
        string backup = Path.Combine(outputDir, "SD-Bridge-previous-" +
            DateTime.Now.ToString("yyyyMMdd-HHmmss", CultureInfo.InvariantCulture) + ".streamDeckPlugin.bak");
        try
        {
            ZipDirectory(tempRoot, staging);
            ValidateGeneratedPackage(staging, bridgeProfiles, "1.20.0." + build.ToString(CultureInfo.InvariantCulture));
            if (File.Exists(installer))
                File.Replace(staging, installer, backup, true);
            else
                File.Move(staging, installer);
        }
        finally
        {
            try { if (File.Exists(staging)) File.Delete(staging); } catch { }
        }

        BridgeState state = new BridgeState();
        state.Build = build;
        state.PluginUuid = PluginUuid;
        state.GeneratedInstaller = installer;
        state.IncludesValidationProfile = includeValidationProfile;
        state.ValidationPassed = oldState != null && oldState.ValidationPassed;
        state.Profiles = bridgeProfiles;
        SaveState(state);

        CPH.LogInfo("[SD Bridge] Generated v1.20.0." + build + " => " + installer);
        try { Directory.Delete(tempRoot, true); } catch { }
        return installer;
    }

    private const string CompanionVersionPrefix = "1.20.0.";

    // A numeric revision by itself is not a plugin version: 1.18.0.20 is
    // OLDER than 1.19.0.18 even though 20 > 18.
    private int GetNextCompanionBuild(int stateBuild)
    {
        Version baseVersion = new Version(1, 20, 0, 0);
        int revision = Math.Max(0, stateBuild);
        string installedVersionText = GetInstalledPluginVersionForReport();
        if (installedVersionText != "<not installed>")
            revision = Math.Max(revision, GetRevisionForTargetSeries(installedVersionText, baseVersion, "installed plugin"));

        string installer = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.DesktopDirectory),
            "SD Bridge", "SD-Bridge.streamDeckPlugin");
        if (File.Exists(installer))
        {
            string packagedVersion = ReadArchivePluginVersion(installer);
            if (string.IsNullOrWhiteSpace(packagedVersion))
                throw new InvalidOperationException("The previous generated installer cannot be read. " +
                    "Move it to a backup location and retry; it will not be overwritten automatically.");
            revision = Math.Max(revision, GetRevisionForTargetSeries(packagedVersion, baseVersion, "previous generated installer"));
        }
        if (revision >= int.MaxValue - 1)
            throw new InvalidOperationException("The companion build counter reached its supported limit.");
        return revision + 1;
    }

    private int GetRevisionForTargetSeries(string value, Version targetBase, string source)
    {
        Version version;
        if (!Version.TryParse(value, out version) || version.Revision < 0 || version.Build < 0)
            throw new InvalidOperationException("Invalid version in " + source + ": " + value);
        if (version.CompareTo(targetBase) > 0 &&
            (version.Major != targetBase.Major || version.Minor != targetBase.Minor || version.Build != targetBase.Build))
        {
            throw new InvalidOperationException("A NEWER SD Bridge companion (" + version +
                ") is already present in " + source + ". Refusing to overwrite it with v0.20.0.");
        }
        return version.Major == targetBase.Major && version.Minor == targetBase.Minor &&
            version.Build == targetBase.Build ? Math.Max(0, version.Revision) : 0;
    }

    private string ReadArchivePluginVersion(string archivePath)
    {
        try
        {
            using (FileStream stream = File.OpenRead(archivePath))
            using (ZipArchive zip = new ZipArchive(stream, ZipArchiveMode.Read))
            {
                ZipArchiveEntry entry = zip.GetEntry(PluginUuid + ".sdPlugin/manifest.json");
                if (entry == null) return null;
                using (StreamReader reader = new StreamReader(entry.Open(), Encoding.UTF8))
                    return (string)JObject.Parse(reader.ReadToEnd())["Version"];
            }
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not read previous installer version: " + ex.Message);
            return null;
        }
    }

    private void ValidateGeneratedPackage(string path, List<BridgeProfileState> profiles, string expectedVersion)
    {
        using (FileStream stream = File.OpenRead(path))
        using (ZipArchive zip = new ZipArchive(stream, ZipArchiveMode.Read))
        {
            string prefix = PluginUuid + ".sdPlugin/";
            ZipArchiveEntry manifestEntry = zip.GetEntry(prefix + "manifest.json");
            ZipArchiveEntry configEntry = zip.GetEntry(prefix + "bridge-config.json");
            ZipArchiveEntry runtimeEntry = zip.GetEntry(prefix + "bin/plugin.js");
            if (manifestEntry == null || configEntry == null || runtimeEntry == null)
                throw new InvalidOperationException("Companion archive is incomplete (manifest/config/runtime missing).");
            JObject manifest;
            JObject config;
            using (StreamReader reader = new StreamReader(manifestEntry.Open(), Encoding.UTF8))
                manifest = JObject.Parse(reader.ReadToEnd());
            using (StreamReader reader = new StreamReader(configEntry.Open(), Encoding.UTF8))
                config = JObject.Parse(reader.ReadToEnd());
            if (!string.Equals((string)manifest["Version"], expectedVersion, StringComparison.Ordinal))
                throw new InvalidOperationException("Generated plugin version does not match the expected version.");
            JArray declared = manifest["Profiles"] as JArray;
            JArray configured = config["profiles"] as JArray;
            if (declared == null || configured == null || declared.Count != profiles.Count || configured.Count != profiles.Count)
                throw new InvalidOperationException("Generated plugin manifest/config has an inconsistent profile count.");
            foreach (BridgeProfileState expected in profiles)
            {
                bool inManifest = declared.OfType<JObject>().Any(x =>
                    string.Equals((string)x["Name"], expected.SdkProfile, StringComparison.OrdinalIgnoreCase) &&
                    (int?)x["DeviceType"] == expected.DeviceType);
                bool inConfig = configured.OfType<JObject>().Any(x =>
                    string.Equals((string)x["key"], expected.Key, StringComparison.OrdinalIgnoreCase) &&
                    string.Equals((string)x["sdkProfile"], expected.SdkProfile, StringComparison.OrdinalIgnoreCase));
                if (!inManifest || !inConfig || zip.GetEntry(prefix + expected.SdkProfile + ".streamDeckProfile") == null)
                    throw new InvalidOperationException("Generated plugin is missing profile " + expected.BridgeName);
            }
        }
    }

    // We only request native switchToProfile after the installed manifest, its
    // configuration AND the live Node.js runtime agree on the target profiles.
    private bool CompanionIsCurrent(BridgeState expectedState, out string issue)
    {
        issue = "";
        try
        {
            string dir = Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData),
                "Elgato", "StreamDeck", "Plugins", PluginUuid + ".sdPlugin");
            string manifestPath = Path.Combine(dir, "manifest.json");
            string configPath = Path.Combine(dir, "bridge-config.json");
            string statusPath = Path.Combine(dir, "runtime-status.json");
            if (!File.Exists(manifestPath) || !File.Exists(configPath))
            {
                issue = "The new SD Bridge companion is not installed. Confirm the plugin update in Stream Deck.";
                return false;
            }
            JObject manifest = JObject.Parse(File.ReadAllText(manifestPath, Encoding.UTF8));
            JObject config = JObject.Parse(File.ReadAllText(configPath, Encoding.UTF8));
            string versionText = (string)manifest["Version"] ?? "";
            Version installed;
            Version wanted = new Version(1, 20, 0, Math.Max(0, expectedState.Build));
            if (!Version.TryParse(versionText, out installed) || installed.CompareTo(wanted) < 0)
            {
                issue = "Installed companion " + versionText + " is older than generated " + wanted +
                    ". Confirm the Stream Deck plugin update (not a profile import).";
                return false;
            }
            JArray declared = manifest["Profiles"] as JArray;
            JArray configured = config["profiles"] as JArray;
            if (declared == null || configured == null)
            {
                issue = "The installed companion manifest/config is incomplete.";
                return false;
            }
            List<BridgeProfileState> expected = expectedState.Profiles ?? new List<BridgeProfileState>();
            if (declared.Count != expected.Count || configured.Count != expected.Count)
            {
                issue = "Installed companion declares " + configured.Count + " profiles, expected " +
                    expected.Count + ". Install the newly generated plugin package.";
                return false;
            }
            foreach (BridgeProfileState p in expected)
            {
                if (!declared.OfType<JObject>().Any(x =>
                    string.Equals((string)x["Name"], p.SdkProfile, StringComparison.OrdinalIgnoreCase) &&
                    (int?)x["DeviceType"] == p.DeviceType) ||
                    !configured.OfType<JObject>().Any(x =>
                    string.Equals((string)x["key"], p.Key, StringComparison.OrdinalIgnoreCase) &&
                    string.Equals((string)x["sdkProfile"], p.SdkProfile, StringComparison.OrdinalIgnoreCase)))
                {
                    issue = "The installed companion does not declare '" + p.BridgeName +
                        "'. Install the generated update before requesting profiles.";
                    return false;
                }
            }
            if (!File.Exists(statusPath))
            {
                issue = "Companion files updated, but the new runtime has not started. " +
                    "Close and reopen Stream Deck (profiles are not deleted).";
                return false;
            }
            JObject status = JObject.Parse(File.ReadAllText(statusPath, Encoding.UTF8));
            int pid = (int?)status["pid"] ?? -1;
            bool connected = (bool?)status["connected"] ?? false;
            JArray runtimeProfiles = status["profiles"] as JArray;
            Version runtimeVersion;
            if (!Version.TryParse((string)status["version"] ?? "", out runtimeVersion) ||
                runtimeVersion.CompareTo(wanted) < 0 || !connected || runtimeProfiles == null ||
                runtimeProfiles.Count != expected.Count || expected.Any(p => !runtimeProfiles.OfType<JObject>().Any(x =>
                    string.Equals((string)x["key"], p.Key, StringComparison.OrdinalIgnoreCase) &&
                    string.Equals((string)x["sdkProfile"], p.SdkProfile, StringComparison.OrdinalIgnoreCase))))
            {
                issue = "The new companion runtime is not ready. Restart only the Stream Deck app and retry Verify.";
                return false;
            }
            try
            {
                using (Process live = Process.GetProcessById(pid))
                {
                    if (live.HasExited)
                    {
                        issue = "Companion runtime has exited. Restart Stream Deck.";
                        return false;
                    }
                }
            }
            catch
            {
                issue = "Companion runtime is not running. Restart Stream Deck.";
                return false;
            }
            return true;
        }
        catch (Exception ex)
        {
            issue = "Companion readiness check failed: " + ex.Message;
            CPH.LogWarn("[SD Bridge] " + issue);
            return false;
        }
    }

    private void CreateEmbeddedValidationProfilePackage(string outputFile)
    {
        byte[] sourceBytes = Convert.FromBase64String(ValidationProfileBase64);
        if (File.Exists(outputFile))
            File.Delete(outputFile);

        using (MemoryStream inputMemory = new MemoryStream(sourceBytes, false))
        using (ZipArchive inputZip = new ZipArchive(inputMemory, ZipArchiveMode.Read, false))
        using (FileStream outputFileStream = new FileStream(outputFile, FileMode.CreateNew, FileAccess.Write, FileShare.None))
        using (ZipArchive outputZip = new ZipArchive(outputFileStream, ZipArchiveMode.Create, false))
        {
            foreach (ZipArchiveEntry sourceEntry in inputZip.Entries)
            {
                ZipArchiveEntry targetEntry = outputZip.CreateEntry(sourceEntry.FullName, CompressionLevel.Optimal);
                bool isRootManifest = sourceEntry.FullName.EndsWith("/manifest.json", StringComparison.OrdinalIgnoreCase) &&
                                      sourceEntry.FullName.Count(c => c == '/') == 1;

                using (Stream target = targetEntry.Open())
                {
                    if (isRootManifest)
                    {
                        string json;
                        using (StreamReader reader = new StreamReader(sourceEntry.Open(), Encoding.UTF8))
                            json = reader.ReadToEnd();
                        JObject manifest = JObject.Parse(json);
                        manifest["Name"] = ValidationProfileDisplayName;
                        JObject device = manifest["Device"] as JObject;
                        if (device != null)
                            device["UUID"] = "";
                        byte[] data = new UTF8Encoding(false).GetBytes(manifest.ToString(Formatting.None));
                        target.Write(data, 0, data.Length);
                    }
                    else if (!sourceEntry.FullName.EndsWith("/", StringComparison.Ordinal))
                    {
                        using (Stream source = sourceEntry.Open())
                            source.CopyTo(target);
                    }
                }
            }
        }
    }

    private void CreateStreamDeckProfilePackage(
        string sourceDir,
        string outputFile,
        string bridgeName,
        string bridgeKey,
        string sourceName)
    {
        if (File.Exists(outputFile))
            File.Delete(outputFile);

        using (FileStream fs = new FileStream(outputFile, FileMode.CreateNew, FileAccess.Write, FileShare.None))
        using (ZipArchive zip = new ZipArchive(fs, ZipArchiveMode.Create))
        {
            string rootName = Path.GetFileName(sourceDir.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar));

            foreach (string file in Directory.GetFiles(sourceDir, "*", SearchOption.AllDirectories))
            {
                string rel = file.Substring(sourceDir.Length)
                    .TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
                    .Replace('\\', '/');

                // Always rewrite our own marker so stale identity metadata can never accumulate.
                if (string.Equals(rel, BridgeMarkerFileName, StringComparison.OrdinalIgnoreCase))
                    continue;

                string entryName = rootName + "/" + rel;
                ZipArchiveEntry entry = zip.CreateEntry(entryName, CompressionLevel.Optimal);

                using (Stream output = entry.Open())
                {
                    if (string.Equals(rel, "manifest.json", StringComparison.OrdinalIgnoreCase))
                    {
                        JObject manifest = JObject.Parse(File.ReadAllText(file, Encoding.UTF8));
                        manifest["Name"] = bridgeName;

                        JObject device = manifest["Device"] as JObject;
                        if (device != null)
                            device["UUID"] = "";

                        byte[] data = new UTF8Encoding(false).GetBytes(manifest.ToString(Formatting.None));
                        output.Write(data, 0, data.Length);
                    }
                    else
                    {
                        using (FileStream input = File.OpenRead(file))
                            input.CopyTo(output);
                    }
                }
            }

            JObject marker = new JObject();
            marker["version"] = BridgeMarkerVersion;
            marker["pluginUuid"] = PluginUuid;
            marker["bridgeKey"] = bridgeKey ?? "";
            marker["sourceName"] = sourceName ?? "";

            ZipArchiveEntry markerEntry = zip.CreateEntry(rootName + "/" + BridgeMarkerFileName, CompressionLevel.Optimal);
            using (Stream markerOutput = markerEntry.Open())
            {
                byte[] markerData = new UTF8Encoding(false).GetBytes(marker.ToString(Formatting.None));
                markerOutput.Write(markerData, 0, markerData.Length);
            }
        }
    }

    private void ZipDirectory(string sourceRoot, string outputZip)
    {
        using (FileStream fs = new FileStream(outputZip, FileMode.CreateNew, FileAccess.Write, FileShare.None))
        using (ZipArchive zip = new ZipArchive(fs, ZipArchiveMode.Create))
        {
            foreach (string dir in Directory.GetDirectories(sourceRoot, "*", SearchOption.AllDirectories))
            {
                string dirRel = dir.Substring(sourceRoot.Length)
                    .TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
                    .Replace('\\', '/')
                    .TrimEnd('/') + "/";
                zip.CreateEntry(dirRel);
            }

            foreach (string file in Directory.GetFiles(sourceRoot, "*", SearchOption.AllDirectories))
            {
                string rel = file.Substring(sourceRoot.Length)
                    .TrimStart(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar)
                    .Replace('\\', '/');

                ZipArchiveEntry entry = zip.CreateEntry(rel, CompressionLevel.Optimal);
                using (Stream output = entry.Open())
                using (FileStream input = File.OpenRead(file))
                    input.CopyTo(output);
            }
        }
    }

    // -------------------------------------------------------------------------
    // PORTABLE STORAGE
    // -------------------------------------------------------------------------

    private static string GetStreamerBotRoot()
    {
        // The inline C# runs inside the Streamer.bot process, so the current
        // executable directory is the authoritative portable installation root.
        try
        {
            using (Process process = Process.GetCurrentProcess())
            {
                if (process.MainModule != null &&
                    !string.IsNullOrWhiteSpace(process.MainModule.FileName))
                {
                    string dir = Path.GetDirectoryName(process.MainModule.FileName);
                    if (!string.IsNullOrWhiteSpace(dir))
                        return dir;
                }
            }
        }
        catch
        {
        }

        // Safe fallback for unusual hosting/debug scenarios.
        string baseDir = AppDomain.CurrentDomain.BaseDirectory;
        if (!string.IsNullOrWhiteSpace(baseDir))
            return baseDir.TrimEnd(Path.DirectorySeparatorChar, Path.AltDirectorySeparatorChar);

        return Environment.CurrentDirectory;
    }

    private void MigrateLegacyStateIfNeeded()
    {
        try
        {
            if (File.Exists(StatePath) || !File.Exists(LegacyStatePath))
                return;

            Directory.CreateDirectory(PortableDataRoot);
            File.Copy(LegacyStatePath, StatePath, false);
            CPH.LogInfo("[SD Bridge] Migrated state.json from legacy %APPDATA% storage to portable Streamer.bot storage: " + StatePath);
        }
        catch (Exception ex)
        {
            // Migration failure must not prevent the addon from starting.
            CPH.LogWarn("[SD Bridge] Could not migrate legacy state.json: " + ex.Message);
        }
    }

    // -------------------------------------------------------------------------
    // STATE
    // -------------------------------------------------------------------------

    private BridgeState LoadState()
    {
        MigrateLegacyStateIfNeeded();
        if (!File.Exists(StatePath))
            return new BridgeState();

        try
        {
            JObject root = JObject.Parse(File.ReadAllText(StatePath, Encoding.UTF8));
            BridgeState state = new BridgeState();
            state.Build = (int?)root["build"] ?? 0;
            state.PluginUuid = (string)root["pluginUuid"] ?? PluginUuid;
            state.GeneratedInstaller = (string)root["generatedInstaller"] ?? "";
            state.IncludesValidationProfile = (bool?)root["includesValidationProfile"] ?? false;
            state.ValidationPassed = (bool?)root["validationPassed"] ?? false;
            state.Profiles = new List<BridgeProfileState>();

            JArray profiles = root["profiles"] as JArray;
            if (profiles != null)
            {
                foreach (JObject p in profiles.OfType<JObject>())
                {
                    BridgeProfileState b = new BridgeProfileState();
                    b.Key = (string)p["key"] ?? "";
                    b.SourceName = (string)p["sourceName"] ?? "";
                    b.SourcePath = (string)p["sourcePath"] ?? "";
                    b.SourceId = (string)p["sourceId"] ?? "";
                    b.BridgeId = (string)p["bridgeId"] ?? "";
                    b.BridgeName = (string)p["bridgeName"] ?? "";
                    b.SdkProfile = (string)p["sdkProfile"] ?? "";
                    b.DeviceType = (int?)p["deviceType"] ?? -1;
                    b.ExpectedPageCount = (int?)p["expectedPageCount"] ?? 0;
                    b.ExpectedPages = new List<string>();
                    JArray pages = p["expectedPages"] as JArray;
                    if (pages != null)
                        b.ExpectedPages.AddRange(pages.Select(x => Convert.ToString(x, CultureInfo.InvariantCulture)));
                    b.Aliases = new List<string>();
                    JArray aliases = p["aliases"] as JArray;
                    if (aliases != null)
                        b.Aliases.AddRange(aliases.Select(x => Convert.ToString(x, CultureInfo.InvariantCulture))
                            .Where(x => !string.IsNullOrWhiteSpace(x)));
                    b.IsValidationTest = (bool?)p["isValidationTest"] ?? false;
                    state.Profiles.Add(b);
                }
            }
            return state;
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not read state.json: " + ex.Message);
            try
            {
                string quarantineDir = Path.Combine(PortableDataRoot, "Backups", "State", "Corrupt");
                Directory.CreateDirectory(quarantineDir);
                string quarantine = Path.Combine(quarantineDir,
                    "state-corrupt-" + DateTime.Now.ToString("yyyy-MM-dd_HH-mm-ss-fff", CultureInfo.InvariantCulture) +
                    "-" + Guid.NewGuid().ToString("N").Substring(0, 8) + ".json");
                try
                {
                    File.Move(StatePath, quarantine);
                }
                catch
                {
                    File.Copy(StatePath, quarantine, false);
                }
                CPH.LogWarn("[SD Bridge] Corrupt state quarantined at: " + quarantine);
            }
            catch (Exception quarantineEx)
            {
                CPH.LogWarn("[SD Bridge] Could not quarantine corrupt state: " + quarantineEx.Message);
            }
            return new BridgeState();
        }
    }

    private void SaveState(BridgeState state)
    {
        Directory.CreateDirectory(PortableDataRoot);
        string temp = StatePath + ".tmp-" + Guid.NewGuid().ToString("N");
        string previous = StatePath + ".previous";
        SaveStateToPath(state, temp);
        try
        {
            if (File.Exists(StatePath))
            {
                try
                {
                    try { if (File.Exists(previous)) File.Delete(previous); } catch { }
                    File.Replace(temp, StatePath, previous, true);
                }
                catch
                {
                    // Same-directory rename fallback: never stream-copy over the live state file.
                    try { if (File.Exists(previous)) File.Delete(previous); } catch { }
                    File.Move(StatePath, previous);
                    try
                    {
                        File.Move(temp, StatePath);
                    }
                    catch
                    {
                        try { if (!File.Exists(StatePath) && File.Exists(previous)) File.Move(previous, StatePath); } catch { }
                        throw;
                    }
                }
            }
            else
            {
                File.Move(temp, StatePath);
            }
        }
        finally
        {
            try { if (File.Exists(temp)) File.Delete(temp); } catch { }
        }
    }

    private StateRebuildResult CleanAndRebuildState()
    {
        Directory.CreateDirectory(PortableDataRoot);

        BridgeState previous = LoadState();
        StateRebuildResult result = new StateRebuildResult();
        result.AliasesBefore = (previous.Profiles ?? new List<BridgeProfileState>())
            .Sum(p => (p.Aliases ?? new List<string>()).Count);

        // Backup first. A manual maintenance action must always be reversible.
        if (File.Exists(StatePath))
        {
            string backupDir = Path.Combine(
                PortableDataRoot,
                "Backups",
                "State",
                DateTime.Now.ToString("yyyy-MM-dd_HH-mm-ss-fff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8));
            Directory.CreateDirectory(backupDir);
            result.BackupPath = Path.Combine(backupDir, "state-before-rebuild.json");
            File.Copy(StatePath, result.BackupPath, true);
        }

        List<ProfileInfo> liveProfiles = ScanProfiles()
            .Where(p => IsBridgeableDeviceType(p.DeviceType))
            .OrderByDescending(p => p.LastWriteUtc)
            .ToList();

        List<BridgeProfileState> installedConfig = LoadInstalledBridgeConfigProfiles();
        List<BridgeProfileState> installedNormal = installedConfig
            .Where(p => !p.IsValidationTest)
            .ToList();

        List<BridgeProfileState> rebuiltProfiles = new List<BridgeProfileState>();
        HashSet<string> usedKeys = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
        HashSet<string> usedLiveIds = new HashSet<string>(StringComparer.OrdinalIgnoreCase);

        // 1) Marker-backed Bridge profiles are authoritative and completely rename-safe.
        foreach (ProfileInfo live in liveProfiles.Where(p => p.IsManagedBridge))
        {
            if (string.IsNullOrWhiteSpace(live.BridgeKey))
                continue;

            if (usedKeys.Contains(live.BridgeKey))
            {
                result.Warnings.Add("Duplicate live Bridge key '" + live.BridgeKey + "' detected; newest profile kept.");
                continue;
            }

            BridgeProfileState installed = installedNormal.FirstOrDefault(p =>
                string.Equals(p.Key, live.BridgeKey, StringComparison.OrdinalIgnoreCase));
            BridgeProfileState old = (previous.Profiles ?? new List<BridgeProfileState>()).FirstOrDefault(p =>
                !p.IsValidationTest &&
                (string.Equals(p.Key, live.BridgeKey, StringComparison.OrdinalIgnoreCase) ||
                 (!string.IsNullOrWhiteSpace(p.BridgeId) &&
                  string.Equals(p.BridgeId, live.Id, StringComparison.OrdinalIgnoreCase))));

            BridgeProfileState rebuilt = CreateRebuiltStateFromLive(live, live.BridgeKey, old, installed);
            rebuiltProfiles.Add(rebuilt);
            usedKeys.Add(rebuilt.Key);
            usedLiveIds.Add(live.Id);
        }

        // 2) Legacy/unmarked [Bridge] profiles are reconciled against the installed plugin config
        // and the previous local folder id. A new key is invented only as a last-resort recovery.
        foreach (ProfileInfo live in liveProfiles
            .Where(p => !p.IsManagedBridge)
            .Where(p => p.Name.EndsWith(BridgeSuffix, StringComparison.OrdinalIgnoreCase))
            .Where(p => !usedLiveIds.Contains(p.Id)))
        {
            BridgeProfileState oldById = (previous.Profiles ?? new List<BridgeProfileState>()).FirstOrDefault(p =>
                !p.IsValidationTest &&
                !string.IsNullOrWhiteSpace(p.BridgeId) &&
                string.Equals(p.BridgeId, live.Id, StringComparison.OrdinalIgnoreCase));

            BridgeProfileState installed = null;
            if (oldById != null && !string.IsNullOrWhiteSpace(oldById.Key))
            {
                installed = installedNormal.FirstOrDefault(p =>
                    string.Equals(p.Key, oldById.Key, StringComparison.OrdinalIgnoreCase));
            }

            if (installed == null)
                installed = ResolveInstalledConfigForRenamedLive(
                    live,
                    previous.Profiles == null
                        ? new List<BridgeProfileState>()
                        : previous.Profiles.Where(p => !p.IsValidationTest).ToList(),
                    installedNormal);

            if (installed == null && oldById == null && installedNormal.Any(p => p.DeviceType == live.DeviceType))
            {
                result.Warnings.Add("Ambiguous legacy Bridge identity for '" + live.Name + "'; no state entry was invented.");
                continue;
            }

            string key = installed != null && !string.IsNullOrWhiteSpace(installed.Key)
                ? installed.Key
                : (oldById != null && !string.IsNullOrWhiteSpace(oldById.Key)
                    ? oldById.Key
                    : MakeKey(StripBridgeSuffix(live.Name)));

            if (usedKeys.Contains(key))
            {
                result.Warnings.Add("Multiple live profiles resolve to Bridge key '" + key + "'; newest profile kept.");
                continue;
            }

            BridgeProfileState rebuilt = CreateRebuiltStateFromLive(live, key, oldById, installed);
            rebuiltProfiles.Add(rebuilt);
            usedKeys.Add(rebuilt.Key);
            usedLiveIds.Add(live.Id);

            // Upgrade the legacy profile so every later scan is independent of its display name.
            TryWriteLiveBridgeMarker(live, rebuilt);
        }

        // 3) Temporary validation state follows what is physically present, not stale JSON.
        ProfileInfo liveValidation = liveProfiles.FirstOrDefault(p =>
            p.DeviceType == ValidationDeviceType &&
            string.Equals(p.Name, ValidationProfileDisplayName, StringComparison.OrdinalIgnoreCase));

        if (liveValidation != null)
        {
            BridgeProfileState installedValidation = installedConfig.FirstOrDefault(p => p.IsValidationTest) ??
                installedConfig.FirstOrDefault(p =>
                    string.Equals(p.Key, ValidationProfileKey, StringComparison.OrdinalIgnoreCase));
            BridgeProfileState oldValidation = (previous.Profiles ?? new List<BridgeProfileState>())
                .FirstOrDefault(p => p.IsValidationTest);

            BridgeProfileState validation = CreateRebuiltStateFromLive(
                liveValidation,
                ValidationProfileKey,
                oldValidation,
                installedValidation);
            validation.SourceName = ValidationProfileName;
            validation.BridgeName = liveValidation.Name;
            validation.SdkProfile = ValidationProfileSdk;
            validation.IsValidationTest = true;
            validation.Aliases = new List<string>();
            rebuiltProfiles.Add(validation);
        }

        BridgeState rebuiltState = new BridgeState();
        rebuiltState.Build = previous.Build;
        rebuiltState.PluginUuid = PluginUuid;
        rebuiltState.GeneratedInstaller =
            !string.IsNullOrWhiteSpace(previous.GeneratedInstaller) && File.Exists(previous.GeneratedInstaller)
                ? previous.GeneratedInstaller
                : "";
        rebuiltState.IncludesValidationProfile = liveValidation != null;
        rebuiltState.ValidationPassed = previous.ValidationPassed;
        rebuiltState.Profiles = rebuiltProfiles;

        SaveState(rebuiltState);

        result.LiveBridgeCount = rebuiltProfiles.Count(p => !p.IsValidationTest);
        result.EntryCount = rebuiltProfiles.Count;
        result.AliasesAfter = rebuiltProfiles.Sum(p => (p.Aliases ?? new List<string>()).Count);
        result.RemovedEntryCount = Math.Max(0,
            (previous.Profiles ?? new List<BridgeProfileState>()).Count - rebuiltProfiles.Count);

        CPH.LogInfo("[SD Bridge] state.json rebuilt: " + result.EntryCount +
            " entries, " + result.AliasesAfter + " aliases, backup=" + (result.BackupPath ?? "<none>"));
        return result;
    }

    private BridgeProfileState CreateRebuiltStateFromLive(
        ProfileInfo live,
        string key,
        BridgeProfileState old,
        BridgeProfileState installed)
    {
        BridgeProfileState rebuilt = new BridgeProfileState();
        rebuilt.Key = key ?? "";
        rebuilt.SourceName =
            installed != null && !string.IsNullOrWhiteSpace(installed.SourceName)
                ? installed.SourceName
                : (old != null && !string.IsNullOrWhiteSpace(old.SourceName)
                    ? old.SourceName
                    : (!string.IsNullOrWhiteSpace(live.BridgeSourceName)
                        ? live.BridgeSourceName
                        : StripBridgeSuffix(live.Name)));
        rebuilt.SourcePath = "";
        rebuilt.SourceId = "";
        rebuilt.BridgeId = live.Id;
        rebuilt.BridgeName = live.Name;
        rebuilt.SdkProfile =
            installed != null && !string.IsNullOrWhiteSpace(installed.SdkProfile)
                ? installed.SdkProfile
                : "profiles/" + rebuilt.Key;
        rebuilt.DeviceType = live.DeviceType;
        rebuilt.ExpectedPageCount = live.Pages == null ? 0 : live.Pages.Count;
        rebuilt.ExpectedPages = new List<string>(live.Pages ?? new List<string>());
        rebuilt.IsValidationTest =
            (installed != null && installed.IsValidationTest) ||
            (old != null && old.IsValidationTest) ||
            string.Equals(rebuilt.Key, ValidationProfileKey, StringComparison.OrdinalIgnoreCase);
        rebuilt.Aliases = BuildCompactedAliases(rebuilt, old, installed);
        return rebuilt;
    }

    private List<string> BuildCompactedAliases(
        BridgeProfileState current,
        BridgeProfileState old,
        BridgeProfileState installed)
    {
        const int MaxHistoricalAliases = 10;
        List<string> candidates = new List<string>();

        Action<string> add = delegate(string value)
        {
            if (string.IsNullOrWhiteSpace(value))
                return;
            if (string.Equals(value, current.Key, StringComparison.OrdinalIgnoreCase) ||
                string.Equals(value, current.SourceName, StringComparison.OrdinalIgnoreCase) ||
                string.Equals(value, current.BridgeName, StringComparison.OrdinalIgnoreCase))
                return;
            if (!candidates.Any(x => string.Equals(x, value, StringComparison.OrdinalIgnoreCase)))
                candidates.Add(value);
        };

        // Highest-value compatibility aliases first.
        if (installed != null)
        {
            add(installed.SourceName);
            add(installed.BridgeName);
            foreach (string alias in installed.Aliases ?? new List<string>())
                add(alias);
        }
        if (old != null)
        {
            add(old.SourceName);
            add(old.BridgeName);

            // Newest historical names tend to be appended last in state.json.
            List<string> history = old.Aliases ?? new List<string>();
            for (int i = history.Count - 1; i >= 0; i--)
                add(history[i]);
        }

        return candidates.Take(MaxHistoricalAliases).ToList();
    }

    private void SaveStateToPath(BridgeState state, string path)
    {
        Directory.CreateDirectory(Path.GetDirectoryName(path));
        JObject root = new JObject();
        root["build"] = state.Build;
        root["pluginUuid"] = state.PluginUuid;
        root["generatedInstaller"] = state.GeneratedInstaller ?? "";
        root["includesValidationProfile"] = state.IncludesValidationProfile;
        root["validationPassed"] = state.ValidationPassed;
        root["storagePath"] = StatePath;

        JArray profiles = new JArray();
        foreach (BridgeProfileState b in state.Profiles ?? new List<BridgeProfileState>())
        {
            JObject p = new JObject();
            p["key"] = b.Key;
            p["sourceName"] = b.SourceName;
            p["sourcePath"] = b.SourcePath ?? "";
            p["sourceId"] = b.SourceId ?? "";
            p["bridgeId"] = b.BridgeId ?? "";
            p["bridgeName"] = b.BridgeName;
            p["sdkProfile"] = b.SdkProfile;
            p["deviceType"] = b.DeviceType;
            p["expectedPageCount"] = b.ExpectedPageCount;
            p["expectedPages"] = new JArray(b.ExpectedPages ?? new List<string>());
            p["aliases"] = new JArray((b.Aliases ?? new List<string>())
                .Where(x => !string.IsNullOrWhiteSpace(x))
                .Distinct(StringComparer.OrdinalIgnoreCase));
            p["isValidationTest"] = b.IsValidationTest;
            profiles.Add(p);
        }
        root["profiles"] = profiles;
        File.WriteAllText(path, root.ToString(Formatting.Indented), new UTF8Encoding(false));
    }

    private List<BridgeProfileState> GetConfiguredProfiles(BridgeState state)
    {
        List<BridgeProfileState> profiles =
            state == null || state.Profiles == null
                ? new List<BridgeProfileState>()
                : state.Profiles
                    .Where(p => !p.IsValidationTest)
                    .Where(p => !string.IsNullOrWhiteSpace(p.Key))
                    .ToList();

        List<ProfileInfo> liveProfiles = ScanProfiles()
            .Where(p => IsBridgeableDeviceType(p.DeviceType))
            .OrderByDescending(p => p.LastWriteUtc)
            .ToList();

        // V11: explicit marker-based reconciliation first. This is the authoritative identity
        // for profiles generated/updated by V11 and remains valid even after a user rename.
        foreach (ProfileInfo live in liveProfiles.Where(p => p.IsManagedBridge))
        {
            BridgeProfileState existing = profiles.FirstOrDefault(p =>
                string.Equals(p.Key, live.BridgeKey, StringComparison.OrdinalIgnoreCase) ||
                (!string.IsNullOrWhiteSpace(p.BridgeId) && string.Equals(p.BridgeId, live.Id, StringComparison.OrdinalIgnoreCase)) ||
                (string.Equals(p.BridgeName, live.Name, StringComparison.OrdinalIgnoreCase) &&
                 (!IsBridgeableDeviceType(p.DeviceType) || p.DeviceType == live.DeviceType)));

            if (existing == null)
            {
                existing = new BridgeProfileState();
                existing.Key = live.BridgeKey;
                existing.SourceName = !string.IsNullOrWhiteSpace(live.BridgeSourceName)
                    ? live.BridgeSourceName
                    : StripBridgeSuffix(live.Name);
                existing.SourcePath = "";
                existing.SourceId = "";
                existing.SdkProfile = "profiles/" + live.BridgeKey;
                existing.DeviceType = live.DeviceType;
                existing.IsValidationTest = false;
                profiles.Add(existing);
            }

            if (string.IsNullOrWhiteSpace(existing.SourceName) && !string.IsNullOrWhiteSpace(live.BridgeSourceName))
                existing.SourceName = live.BridgeSourceName;

            EnsureAlias(existing, existing.SourceName);
            EnsureAlias(existing, existing.BridgeName);
            EnsureAlias(existing, live.Name);
            existing.BridgeId = live.Id;
            existing.BridgeName = live.Name;
            existing.DeviceType = live.DeviceType;
            existing.ExpectedPageCount = live.Pages.Count;
            existing.ExpectedPages = new List<string>(live.Pages);
            if (string.IsNullOrWhiteSpace(existing.SdkProfile))
                existing.SdkProfile = "profiles/" + existing.Key;
        }

        // Legacy recovery for V10/V14 Bridge profiles that do not have the marker yet.
        // V15 treats the bridge-config.json of the CURRENTLY INSTALLED plugin as authoritative:
        // display names may change, but the installed profile key must never be regenerated from
        // the new display name. This prevents a rename from creating a second logical identity.
        List<BridgeProfileState> installedConfig = LoadInstalledBridgeConfigProfiles()
            .Where(p => !p.IsValidationTest)
            .ToList();

        foreach (ProfileInfo live in liveProfiles
            .Where(p => !p.IsManagedBridge)
            .Where(p => p.Name.EndsWith(BridgeSuffix, StringComparison.OrdinalIgnoreCase)))
        {
            string sourceName = StripBridgeSuffix(live.Name);

            BridgeProfileState existing = profiles.FirstOrDefault(p =>
                (!string.IsNullOrWhiteSpace(p.BridgeId) && string.Equals(p.BridgeId, live.Id, StringComparison.OrdinalIgnoreCase)) ||
                (string.Equals(p.BridgeName, live.Name, StringComparison.OrdinalIgnoreCase) &&
                 (!IsBridgeableDeviceType(p.DeviceType) || p.DeviceType == live.DeviceType)) ||
                (string.Equals(p.SourceName, sourceName, StringComparison.OrdinalIgnoreCase) &&
                 (!IsBridgeableDeviceType(p.DeviceType) || p.DeviceType == live.DeviceType)) ||
                (p.Aliases != null && p.Aliases.Any(a => string.Equals(a, live.Name, StringComparison.OrdinalIgnoreCase))));

            BridgeProfileState authoritative = ResolveInstalledConfigForRenamedLive(live, profiles, installedConfig);
            if (authoritative != null)
            {
                BridgeProfileState authoritativeState = profiles.FirstOrDefault(p =>
                    string.Equals(p.Key, authoritative.Key, StringComparison.OrdinalIgnoreCase));

                if (authoritativeState == null)
                {
                    authoritativeState = CloneBridgeState(authoritative);
                    profiles.Add(authoritativeState);
                }

                // V14 could already have persisted a bogus state generated from the renamed display name.
                // Keep its names as aliases, then remove that bogus logical identity from the reconciled list.
                if (existing != null && !string.Equals(existing.Key, authoritativeState.Key, StringComparison.OrdinalIgnoreCase))
                {
                    EnsureAlias(authoritativeState, existing.SourceName);
                    EnsureAlias(authoritativeState, existing.BridgeName);
                    foreach (string alias in existing.Aliases ?? new List<string>())
                        EnsureAlias(authoritativeState, alias);

                    bool existingKeyIsInstalled = installedConfig.Any(x =>
                        string.Equals(x.Key, existing.Key, StringComparison.OrdinalIgnoreCase));
                    if (!existingKeyIsInstalled)
                        profiles.Remove(existing);
                }

                existing = authoritativeState;
            }

            if (existing != null)
            {
                EnsureAlias(existing, existing.SourceName);
                EnsureAlias(existing, existing.BridgeName);
                EnsureAlias(existing, live.Name);
                existing.BridgeId = live.Id;
                existing.BridgeName = live.Name;
                existing.DeviceType = live.DeviceType;
                existing.ExpectedPageCount = live.Pages.Count;
                existing.ExpectedPages = new List<string>(live.Pages);
                TryWriteLiveBridgeMarker(live, existing);
                continue;
            }

            // Fail closed when an unmarked legacy profile cannot be mapped uniquely.
            List<BridgeProfileState> sameTypeInstalled = installedConfig
                .Where(x => x.DeviceType == live.DeviceType)
                .ToList();
            if (sameTypeInstalled.Count > 0)
            {
                CPH.LogWarn("[SD Bridge] Ambiguous legacy Bridge identity for '" + live.Name +
                    "'. Run Clean / Rebuild state or reinstall/update the Bridge before switching it. No new key was invented.");
                continue;
            }

            // First-discovery fallback only when no installed identity can plausibly own this profile.
            BridgeProfileState b = new BridgeProfileState();
            b.SourceName = sourceName;
            b.SourcePath = "";
            b.SourceId = "";
            b.BridgeId = live.Id;
            b.BridgeName = live.Name;
            b.Key = MakeKey(sourceName);
            b.SdkProfile = "profiles/" + b.Key;
            b.DeviceType = live.DeviceType;
            b.ExpectedPageCount = live.Pages.Count;
            b.ExpectedPages = new List<string>(live.Pages);
            b.Aliases = new List<string>();
            EnsureAlias(b, sourceName);
            EnsureAlias(b, live.Name);
            b.IsValidationTest = false;
            profiles.Add(b);
        }

        return profiles;
    }

    private void EnsureAlias(BridgeProfileState state, string value)
    {
        if (state == null || string.IsNullOrWhiteSpace(value))
            return;
        if (state.Aliases == null)
            state.Aliases = new List<string>();
        if (!state.Aliases.Any(x => string.Equals(x, value, StringComparison.OrdinalIgnoreCase)))
            state.Aliases.Add(value);
    }

    private BridgeProfileState CloneBridgeState(BridgeProfileState source)
    {
        BridgeProfileState b = new BridgeProfileState();
        if (source == null)
            return b;
        b.Key = source.Key;
        b.SourceName = source.SourceName;
        b.SourcePath = source.SourcePath;
        b.SourceId = source.SourceId;
        b.BridgeId = source.BridgeId;
        b.BridgeName = source.BridgeName;
        b.SdkProfile = source.SdkProfile;
        b.DeviceType = source.DeviceType;
        b.ExpectedPageCount = source.ExpectedPageCount;
        b.ExpectedPages = new List<string>(source.ExpectedPages ?? new List<string>());
        b.Aliases = new List<string>(source.Aliases ?? new List<string>());
        b.IsValidationTest = source.IsValidationTest;
        return b;
    }

    private List<BridgeProfileState> LoadInstalledBridgeConfigProfiles()
    {
        List<BridgeProfileState> result = new List<BridgeProfileState>();
        try
        {
            string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
            string configPath = Path.Combine(appData, "Elgato", "StreamDeck", "Plugins",
                PluginUuid + ".sdPlugin", "bridge-config.json");
            if (!File.Exists(configPath))
                return result;

            JObject root = JObject.Parse(File.ReadAllText(configPath, Encoding.UTF8));
            JArray profiles = root["profiles"] as JArray;
            if (profiles == null)
                return result;

            foreach (JObject p in profiles.OfType<JObject>())
            {
                BridgeProfileState b = new BridgeProfileState();
                b.Key = (string)p["key"] ?? "";
                b.SourceName = (string)p["sourceName"] ?? "";
                b.BridgeId = (string)p["bridgeId"] ?? "";
                b.BridgeName = (string)p["displayName"] ?? "";
                b.SdkProfile = (string)p["sdkProfile"] ?? "";
                b.DeviceType = (int?)p["deviceType"] ?? -1;
                b.IsValidationTest = (bool?)p["isValidationTest"] ?? false;
                b.Aliases = new List<string>();
                JArray storedAliases = p["aliases"] as JArray;
                if (storedAliases != null)
                {
                    foreach (JToken aliasToken in storedAliases)
                        EnsureAlias(b, Convert.ToString(aliasToken, CultureInfo.InvariantCulture));
                }
                EnsureAlias(b, b.SourceName);
                EnsureAlias(b, b.BridgeName);
                if (!string.IsNullOrWhiteSpace(b.Key))
                    result.Add(b);
            }
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not read installed bridge-config.json: " + ex.Message);
        }
        return result;
    }

    private BridgeProfileState ResolveInstalledConfigForRenamedLive(
        ProfileInfo live,
        List<BridgeProfileState> currentStates,
        List<BridgeProfileState> installedConfig)
    {
        if (live == null || installedConfig == null || installedConfig.Count == 0)
            return null;

        List<BridgeProfileState> candidates = installedConfig
            .Where(x => !x.IsValidationTest)
            .Where(x => !IsBridgeableDeviceType(x.DeviceType) || x.DeviceType == live.DeviceType)
            .ToList();
        if (candidates.Count == 0)
            return null;

        // Old installed display/source names are still useful aliases.
        BridgeProfileState exact = candidates.FirstOrDefault(x =>
            string.Equals(x.BridgeName, live.Name, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(x.SourceName, StripBridgeSuffix(live.Name), StringComparison.OrdinalIgnoreCase));
        if (exact != null)
            return exact;

        // If state remembers the original profile and its page fingerprint is unchanged,
        // that gives us a strong rename-only match even if Stream Deck changed the folder id.
        List<BridgeProfileState> pageMatches = new List<BridgeProfileState>();
        foreach (BridgeProfileState cfg in candidates)
        {
            BridgeProfileState state = (currentStates ?? new List<BridgeProfileState>()).FirstOrDefault(x =>
                string.Equals(x.Key, cfg.Key, StringComparison.OrdinalIgnoreCase));
            if (state == null || state.ExpectedPages == null || live.Pages == null)
                continue;
            if (state.ExpectedPages.SequenceEqual(live.Pages, StringComparer.OrdinalIgnoreCase))
                pageMatches.Add(cfg);
        }
        if (pageMatches.Count == 1)
            return pageMatches[0];

        // Common case: one bridged profile for this device type. The installed plugin key is
        // authoritative; the live Stream Deck display name is not allowed to create a new key.
        if (candidates.Count == 1)
            return candidates[0];

        return null;
    }

    private void TryWriteLiveBridgeMarker(ProfileInfo live, BridgeProfileState state)
    {
        if (live == null || state == null || string.IsNullOrWhiteSpace(live.SourcePath) ||
            string.IsNullOrWhiteSpace(state.Key))
            return;
        try
        {
            string markerPath = Path.Combine(live.SourcePath, BridgeMarkerFileName);
            JObject marker = new JObject();
            marker["version"] = BridgeMarkerVersion;
            marker["pluginUuid"] = PluginUuid;
            marker["bridgeKey"] = state.Key;
            marker["sourceName"] = state.SourceName ?? StripBridgeSuffix(live.Name);
            File.WriteAllText(markerPath, marker.ToString(Formatting.Indented), new UTF8Encoding(false));
            live.IsManagedBridge = true;
            live.BridgeKey = state.Key;
            live.BridgeSourceName = state.SourceName ?? "";
            live.BridgeMarkerVersion = BridgeMarkerVersion;
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not stamp live Bridge identity marker: " + ex.Message);
        }
    }

    private List<BridgeProfileState> GetSwitchableProfiles(BridgeState state)
    {
        List<BridgeProfileState> profiles = GetConfiguredProfiles(state);

        if (state != null && state.Profiles != null)
        {
            foreach (BridgeProfileState p in state.Profiles
                .Where(x => x.IsValidationTest)
                .Where(x => !string.IsNullOrWhiteSpace(x.Key)))
            {
                bool exists = profiles.Any(x =>
                    string.Equals(x.Key, p.Key, StringComparison.OrdinalIgnoreCase) ||
                    string.Equals(x.BridgeName, p.BridgeName, StringComparison.OrdinalIgnoreCase));

                if (!exists)
                    profiles.Add(p);
            }
        }

        return profiles;
    }

    private BridgeProfileState ResolveConfiguredProfile(List<BridgeProfileState> profiles, string requested)
    {
        if (profiles == null || profiles.Count == 0)
            return null;
        if (string.IsNullOrWhiteSpace(requested))
            return profiles.Count == 1 ? profiles[0] : null;

        return profiles.FirstOrDefault(p =>
            string.Equals(p.Key, requested, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(p.SourceName, requested, StringComparison.OrdinalIgnoreCase) ||
            string.Equals(p.BridgeName, requested, StringComparison.OrdinalIgnoreCase) ||
            (p.Aliases != null && p.Aliases.Any(a =>
                string.Equals(a, requested, StringComparison.OrdinalIgnoreCase))));
    }

    private void PersistReconciledState(BridgeState state, List<BridgeProfileState> configuredProfiles)
    {
        try
        {
            if (state == null)
                state = new BridgeState();

            List<BridgeProfileState> validation = state.Profiles == null
                ? new List<BridgeProfileState>()
                : state.Profiles.Where(p => p.IsValidationTest).ToList();

            state.Profiles = new List<BridgeProfileState>();
            state.Profiles.AddRange(configuredProfiles ?? new List<BridgeProfileState>());
            state.Profiles.AddRange(validation);
            SaveState(state);
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not persist reconciled Bridge state: " + ex.Message);
        }
    }

    private string NormalizeBridgeName(string name)
    {
        string baseName = StripBridgeSuffix(name);
        if (string.IsNullOrWhiteSpace(baseName))
            baseName = "Stream Deck Profile";
        return baseName.TrimEnd() + BridgeSuffix;
    }

    private string StripBridgeSuffix(string name)
    {
        string value = (name ?? "").TrimEnd();
        while (value.EndsWith(BridgeSuffix, StringComparison.OrdinalIgnoreCase))
            value = value.Substring(0, value.Length - BridgeSuffix.Length).TrimEnd();
        return value;
    }

    private bool HasRepeatedBridgeSuffix(string name)
    {
        string value = (name ?? "").TrimEnd();
        if (!value.EndsWith(BridgeSuffix, StringComparison.OrdinalIgnoreCase))
            return false;

        value = value.Substring(0, value.Length - BridgeSuffix.Length).TrimEnd();
        return value.EndsWith(BridgeSuffix, StringComparison.OrdinalIgnoreCase);
    }

