    // -------------------------------------------------------------------------
    // WPF WINDOW PLACEMENT
    // -------------------------------------------------------------------------
    // Kept in a dedicated portable file so Clean / Rebuild state does not
    // affect the operator's UI layout. Coordinates are WPF device-independent
    // pixels and are validated against the current virtual desktop before use.

    private void EnableWindowPlacement(Window window, string key)
    {
        if (window == null || string.IsNullOrWhiteSpace(key))
            return;

        try
        {
            JObject root = LoadWindowPlacementRoot();
            JObject saved = root[key] as JObject;
            if (saved != null)
            {
                double left = (double?)saved["left"] ?? double.NaN;
                double top = (double?)saved["top"] ?? double.NaN;
                double width = (double?)saved["width"] ?? window.Width;
                double height = (double?)saved["height"] ?? window.Height;
                bool maximized = (bool?)saved["maximized"] ?? false;

                width = Math.Max(window.MinWidth, width);
                height = Math.Max(window.MinHeight, height);

                if (IsSavedPlacementVisible(left, top, width, height))
                {
                    window.WindowStartupLocation = WindowStartupLocation.Manual;
                    window.Left = left;
                    window.Top = top;
                    window.Width = width;
                    window.Height = height;

                    if (maximized)
                        window.WindowState = WindowState.Maximized;
                }
            }
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not restore WPF window placement: " + ex.Message);
        }

        window.Closing += delegate
        {
            SaveWindowPlacement(window, key);
        };
    }

    private JObject LoadWindowPlacementRoot()
    {
        try
        {
            if (!File.Exists(WindowPlacementPath))
                return new JObject();

            JObject root = JObject.Parse(File.ReadAllText(WindowPlacementPath, Encoding.UTF8));
            return root ?? new JObject();
        }
        catch
        {
            return new JObject();
        }
    }

    private void SaveWindowPlacement(Window window, string key)
    {
        if (window == null || string.IsNullOrWhiteSpace(key))
            return;

        try
        {
            Rect bounds = window.WindowState == WindowState.Normal
                ? new Rect(window.Left, window.Top, window.ActualWidth > 0 ? window.ActualWidth : window.Width,
                    window.ActualHeight > 0 ? window.ActualHeight : window.Height)
                : window.RestoreBounds;

            if (double.IsNaN(bounds.Left) || double.IsNaN(bounds.Top) ||
                double.IsInfinity(bounds.Left) || double.IsInfinity(bounds.Top) ||
                bounds.Width <= 0 || bounds.Height <= 0)
                return;

            JObject root = LoadWindowPlacementRoot();
            root[key] = new JObject
            {
                ["left"] = bounds.Left,
                ["top"] = bounds.Top,
                ["width"] = bounds.Width,
                ["height"] = bounds.Height,
                ["maximized"] = window.WindowState == WindowState.Maximized
            };

            Directory.CreateDirectory(PortableDataRoot);

            string temp = WindowPlacementPath + ".tmp-" + Guid.NewGuid().ToString("N");
            File.WriteAllText(temp, root.ToString(Formatting.Indented), new UTF8Encoding(false));

            if (File.Exists(WindowPlacementPath))
            {
                try
                {
                    File.Replace(temp, WindowPlacementPath, null, true);
                }
                catch
                {
                    File.Delete(WindowPlacementPath);
                    File.Move(temp, WindowPlacementPath);
                }
            }
            else
            {
                File.Move(temp, WindowPlacementPath);
            }
        }
        catch (Exception ex)
        {
            CPH.LogWarn("[SD Bridge] Could not save WPF window placement: " + ex.Message);
        }
    }

    private bool IsSavedPlacementVisible(double left, double top, double width, double height)
    {
        if (double.IsNaN(left) || double.IsNaN(top) ||
            double.IsInfinity(left) || double.IsInfinity(top) ||
            width <= 0 || height <= 0)
            return false;

        Rect saved = new Rect(left, top, width, height);
        Rect desktop = new Rect(
            SystemParameters.VirtualScreenLeft,
            SystemParameters.VirtualScreenTop,
            SystemParameters.VirtualScreenWidth,
            SystemParameters.VirtualScreenHeight);

        Rect visible = Rect.Intersect(saved, desktop);

        // Require enough of the title/content area to remain reachable.
        return !visible.IsEmpty && visible.Width >= 80 && visible.Height >= 60;
    }

    private Window CreateWindow(string title, double width, double height)
    {
        Window w = new Window();
        w.Title = title;
        w.Width = width;
        w.Height = height;
        w.MinWidth = Math.Min(width, 700);
        w.MinHeight = Math.Min(height, 500);
        w.WindowStartupLocation = WindowStartupLocation.CenterScreen;
        w.Background = ThemeBackground();
        w.Foreground = Brushes.White;
        w.FontFamily = new FontFamily("Segoe UI");
        w.FontSize = 12;
        w.UseLayoutRounding = true;
        w.SnapsToDevicePixels = true;
        w.WindowStyle = WindowStyle.None;
        w.ResizeMode = ResizeMode.CanResize;

        System.Windows.Shell.WindowChrome chrome = new System.Windows.Shell.WindowChrome();
        chrome.CaptionHeight = 0;
        chrome.ResizeBorderThickness = new Thickness(6);
        chrome.GlassFrameThickness = new Thickness(0);
        chrome.CornerRadius = new CornerRadius(10);
        chrome.UseAeroCaptionButtons = false;
        System.Windows.Shell.WindowChrome.SetWindowChrome(w, chrome);

        try
        {
            w.Icon = LoadBrandImageSource();
        }
        catch { }

        w.SourceInitialized += delegate
        {
            TryApplyRoundedWindowCorners(w);
        };

        return w;
    }

    [System.Runtime.InteropServices.DllImport("dwmapi.dll")]
    private static extern int DwmSetWindowAttribute(
        IntPtr hwnd,
        int dwAttribute,
        ref int pvAttribute,
        int cbAttribute);

    private void TryApplyRoundedWindowCorners(Window window)
    {
        if (window == null)
            return;

        try
        {
            IntPtr hwnd = new System.Windows.Interop.WindowInteropHelper(window).Handle;
            if (hwnd == IntPtr.Zero)
                return;

            // Windows 11: DWMWA_WINDOW_CORNER_PREFERENCE = 33,
            // DWMWCP_ROUND = 2. Unsupported systems simply ignore/fail safely.
            int preference = 2;
            DwmSetWindowAttribute(hwnd, 33, ref preference, sizeof(int));
        }
        catch
        {
            // WindowChrome.CornerRadius remains the visual fallback.
        }
    }

    private ImageSource LoadBrandImageSource()
    {
        return LoadBrandImageSource(0);
    }

    private ImageSource LoadBrandTitleBarImageSource()
    {
        // Decode close to the final title-bar size to avoid noisy downscaling artifacts.
        return LoadBrandImageSource(20);
    }

    private ImageSource LoadBrandImageSource(int decodePixelSize)
    {
        byte[] bytes = Convert.FromBase64String(PluginIconBase64);
        using (MemoryStream stream = new MemoryStream(bytes))
        {
            System.Windows.Media.Imaging.BitmapImage bitmap = new System.Windows.Media.Imaging.BitmapImage();
            bitmap.BeginInit();
            bitmap.CacheOption = System.Windows.Media.Imaging.BitmapCacheOption.OnLoad;
            bitmap.CreateOptions = System.Windows.Media.Imaging.BitmapCreateOptions.PreservePixelFormat;
            if (decodePixelSize > 0)
            {
                bitmap.DecodePixelWidth = decodePixelSize;
                bitmap.DecodePixelHeight = decodePixelSize;
            }
            bitmap.StreamSource = stream;
            bitmap.EndInit();
            bitmap.Freeze();
            return bitmap;
        }
    }

    private void SetWindowContent(Window window, UIElement body)
    {
        if (window == null)
            return;

        Grid shell = new Grid();
        shell.RowDefinitions.Add(new RowDefinition { Height = new GridLength(38) });
        shell.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        shell.Background = ThemeBackground();

        Border frame = new Border
        {
            BorderBrush = ThemeBorder(),
            BorderThickness = new Thickness(1),
            Background = ThemeBackground(),
            CornerRadius = new CornerRadius(10),
            SnapsToDevicePixels = true
        };

        Grid framed = new Grid();
        framed.RowDefinitions.Add(new RowDefinition { Height = new GridLength(38) });
        framed.RowDefinitions.Add(new RowDefinition { Height = new GridLength(1, GridUnitType.Star) });
        frame.Child = framed;

        Grid titleBar = new Grid
        {
            Height = 38,
            Background = ThemeBackground()
        };
        titleBar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });
        titleBar.ColumnDefinitions.Add(new ColumnDefinition { Width = new GridLength(1, GridUnitType.Star) });
        titleBar.ColumnDefinitions.Add(new ColumnDefinition { Width = GridLength.Auto });

        Image logo = new Image
        {
            Source = LoadBrandTitleBarImageSource(),
            Width = 16,
            Height = 16,
            Stretch = Stretch.Uniform,
            Margin = new Thickness(10, 0, 8, 0),
            VerticalAlignment = VerticalAlignment.Center,
            SnapsToDevicePixels = true,
            UseLayoutRounding = true,
            IsHitTestVisible = false
        };
        System.Windows.Media.RenderOptions.SetBitmapScalingMode(logo, System.Windows.Media.BitmapScalingMode.HighQuality);
        Grid.SetColumn(logo, 0);
        titleBar.Children.Add(logo);

        TextBlock title = new TextBlock
        {
            Text = window.Title,
            Foreground = BrushFromRgb(224, 228, 236),
            FontSize = 11.5,
            FontWeight = FontWeights.SemiBold,
            VerticalAlignment = VerticalAlignment.Center,
            TextTrimming = TextTrimming.CharacterEllipsis,
            IsHitTestVisible = false
        };
        Grid.SetColumn(title, 1);
        titleBar.Children.Add(title);

        StackPanel captionButtons = new StackPanel
        {
            Orientation = Orientation.Horizontal,
            HorizontalAlignment = HorizontalAlignment.Right,
            VerticalAlignment = VerticalAlignment.Stretch
        };

        Button minimize = MakeCaptionButton("—", false);
        Button maximize = MakeCaptionButton("□", false);
        Button close = MakeCaptionButton("×", true);

        minimize.ToolTip = "Minimize";
        maximize.ToolTip = "Maximize";
        close.ToolTip = "Close";

        minimize.Click += delegate { window.WindowState = WindowState.Minimized; };
        maximize.Click += delegate
        {
            window.WindowState = window.WindowState == WindowState.Maximized
                ? WindowState.Normal
                : WindowState.Maximized;
        };
        close.Click += delegate { window.Close(); };

        Action updateMaximizeGlyph = delegate
        {
            maximize.Content = window.WindowState == WindowState.Maximized ? "❐" : "□";
            maximize.ToolTip = window.WindowState == WindowState.Maximized ? "Restore" : "Maximize";
        };
        window.StateChanged += delegate { updateMaximizeGlyph(); };
        updateMaximizeGlyph();

        captionButtons.Children.Add(minimize);
        captionButtons.Children.Add(maximize);
        captionButtons.Children.Add(close);
        Grid.SetColumn(captionButtons, 2);
        titleBar.Children.Add(captionButtons);

        titleBar.MouseLeftButtonDown += delegate(object sender, System.Windows.Input.MouseButtonEventArgs e)
        {
            if (e.ChangedButton != System.Windows.Input.MouseButton.Left)
                return;

            if (e.ClickCount == 2 && window.ResizeMode != ResizeMode.NoResize)
            {
                window.WindowState = window.WindowState == WindowState.Maximized
                    ? WindowState.Normal
                    : WindowState.Maximized;
                return;
            }

            try
            {
                if (window.WindowState == WindowState.Maximized)
                    window.WindowState = WindowState.Normal;
                window.DragMove();
            }
            catch { }
        };

        Grid.SetRow(titleBar, 0);
        framed.Children.Add(titleBar);

        Border bodyHost = new Border
        {
            Background = ThemeBackground(),
            Child = body
        };
        Grid.SetRow(bodyHost, 1);
        framed.Children.Add(bodyHost);

        window.Content = frame;
    }

    private Button MakeCaptionButton(string text, bool closeButton)
    {
        Button button = new Button
        {
            Content = text,
            Width = 46,
            Height = 36,
            Margin = new Thickness(0),
            Padding = new Thickness(0),
            BorderThickness = new Thickness(0),
            Background = Brushes.Transparent,
            Foreground = BrushFromRgb(205, 211, 222),
            FontFamily = new FontFamily("Segoe UI Symbol"),
            FontSize = closeButton ? 16 : 13,
            Focusable = false,
            Cursor = System.Windows.Input.Cursors.Arrow
        };

        Brush normalBackground = Brushes.Transparent;
        Brush hoverBackground = closeButton ? BrushFromRgb(196, 43, 28) : BrushFromRgb(43, 47, 57);
        Brush pressedBackground = closeButton ? BrushFromRgb(158, 35, 24) : BrushFromRgb(54, 59, 70);

        button.MouseEnter += delegate { button.Background = hoverBackground; };
        button.MouseLeave += delegate { button.Background = normalBackground; };
        button.PreviewMouseLeftButtonDown += delegate { button.Background = pressedBackground; };
        button.PreviewMouseLeftButtonUp += delegate { button.Background = hoverBackground; };

        return button;
    }

