    private string FormatPagesPreview(List<string> pages)
    {
        if (pages == null || pages.Count == 0)
            return "No page detected";

        int shown = Math.Min(pages.Count, 5);
        List<string> values = new List<string>();

        for (int i = 0; i < shown; i++)
            values.Add((i + 1).ToString(CultureInfo.InvariantCulture) + ". " + (pages[i] ?? "Page"));

        string value = string.Join("  •  ", values);

        if (pages.Count > shown)
            value += "  •  +" + (pages.Count - shown).ToString(CultureInfo.InvariantCulture);

        return value;
    }

