    private Button MakeButton(string text, double width, string variant)
    {
        Brush background = ThemeControl();
        Brush foreground = Brushes.White;
        Brush border = ThemeBorder();

        if (string.Equals(variant, "primary", StringComparison.OrdinalIgnoreCase))
        {
            background = ThemeControl();
            foreground = Brushes.White;
            border = ThemeAccent();
        }
        else if (string.Equals(variant, "danger", StringComparison.OrdinalIgnoreCase))
        {
            background = ThemeControl();
            foreground = ThemeDanger();
            border = ThemeBorder();
        }

        Button button = new Button
        {
            Content = text,
            Width = width,
            Height = 36,
            Margin = new Thickness(8, 0, 0, 0),
            Background = background,
            Foreground = foreground,
            BorderBrush = border,
            BorderThickness = new Thickness(1),
            FontSize = 11.5,
            FontWeight = FontWeights.Normal,
            Cursor = System.Windows.Input.Cursors.Hand
        };

        Style style = new Style(typeof(Button));
        style.Setters.Add(new Setter(Button.BackgroundProperty, background));
        style.Setters.Add(new Setter(Button.ForegroundProperty, foreground));
        style.Setters.Add(new Setter(Button.BorderBrushProperty, border));
        style.Setters.Add(new Setter(Button.BorderThicknessProperty, new Thickness(1)));

        Trigger hover = new Trigger
        {
            Property = Button.IsMouseOverProperty,
            Value = true
        };
        hover.Setters.Add(new Setter(Button.BackgroundProperty, new SolidColorBrush(Color.FromRgb(56, 56, 60))));
        style.Triggers.Add(hover);

        Trigger disabled = new Trigger
        {
            Property = Button.IsEnabledProperty,
            Value = false
        };
        disabled.Setters.Add(new Setter(Button.OpacityProperty, 0.45));
        style.Triggers.Add(disabled);

        ControlTemplate template = new ControlTemplate(typeof(Button));
        FrameworkElementFactory bd = new FrameworkElementFactory(typeof(Border));
        bd.SetValue(Border.CornerRadiusProperty, new CornerRadius(4));
        bd.SetBinding(Border.BackgroundProperty,
            new System.Windows.Data.Binding("Background")
            {
                RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)
            });
        bd.SetBinding(Border.BorderBrushProperty,
            new System.Windows.Data.Binding("BorderBrush")
            {
                RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)
            });
        bd.SetBinding(Border.BorderThicknessProperty,
            new System.Windows.Data.Binding("BorderThickness")
            {
                RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)
            });

        FrameworkElementFactory cp = new FrameworkElementFactory(typeof(ContentPresenter));
        cp.SetValue(ContentPresenter.HorizontalAlignmentProperty, HorizontalAlignment.Center);
        cp.SetValue(ContentPresenter.VerticalAlignmentProperty, VerticalAlignment.Center);
        cp.SetBinding(ContentPresenter.ContentProperty,
            new System.Windows.Data.Binding("Content")
            {
                RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)
            });
        cp.SetBinding(System.Windows.Documents.TextElement.ForegroundProperty,
            new System.Windows.Data.Binding("Foreground")
            {
                RelativeSource = new System.Windows.Data.RelativeSource(System.Windows.Data.RelativeSourceMode.TemplatedParent)
            });

        bd.AppendChild(cp);
        template.VisualTree = bd;
        style.Setters.Add(new Setter(Button.TemplateProperty, template));
        button.Style = style;

        return button;
    }

    private void ShowModernMessage(Window owner, string title, string message, string type)
    {
        MessageBoxImage icon = MessageBoxImage.Information;

        if (string.Equals(type, "warning", StringComparison.OrdinalIgnoreCase))
            icon = MessageBoxImage.Warning;
        else if (string.Equals(type, "error", StringComparison.OrdinalIgnoreCase))
            icon = MessageBoxImage.Error;

        MessageBox.Show(owner, message, title, MessageBoxButton.OK, icon);
    }

    private TextBlock LabelText(string text)
    {
        return new TextBlock
        {
            Text = text,
            Foreground = new SolidColorBrush(Color.FromRgb(185, 185, 185)),
            FontWeight = FontWeights.SemiBold
        };
    }

    private string MakeKey(string name)
    {
        string value = (name ?? "").ToLowerInvariant();
        StringBuilder s = new StringBuilder();
        bool dash = false;

        foreach (char c in value)
        {
            if ((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))
            {
                s.Append(c);
                dash = false;
            }
            else if (!dash && s.Length > 0)
            {
                s.Append('-');
                dash = true;
            }
        }

        string result = s.ToString().Trim('-');
        if (string.IsNullOrWhiteSpace(result))
            result = "profile";
        return result;
    }

    private string UniqueKey(string baseKey, HashSet<string> used)
    {
        if (!used.Contains(baseKey))
            return baseKey;

        int n = 2;
        while (used.Contains(baseKey + "-" + n.ToString(CultureInfo.InvariantCulture)))
            n++;
        return baseKey + "-" + n.ToString(CultureInfo.InvariantCulture);
    }

    private string ProfileIdentityKey(string name, int deviceType)
    {
        return (name ?? "").Trim().ToLowerInvariant() + "|" +
               deviceType.ToString(CultureInfo.InvariantCulture);
    }

    private bool IsBridgeableDeviceType(int type)
    {
        // Stream Deck's current manifest schema defines DeviceType values 0..13.
        // Keep the exact detected type all the way through state -> manifest -> runtime.
        return type >= MinOfficialDeviceType && type <= MaxOfficialDeviceType;
    }

    private string DeviceTypeName(int type)
    {
        switch (type)
        {
            case 0: return "Stream Deck";
            case 1: return "Stream Deck Mini";
            case 2: return "Stream Deck XL";
            case 3: return "Stream Deck Mobile";
            case 4: return "Corsair GKeys";
            case 5: return "Stream Deck Pedal";
            case 6: return "Corsair Voyager";
            case 7: return "Stream Deck +";
            case 8: return "SCUF Controller";
            case 9: return "Stream Deck Neo";
            case 10: return "Stream Deck Studio";
            case 11: return "Virtual Stream Deck";
            case 12: return "Galleon 100 SD";
            case 13: return "Stream Deck + XL";
            default: return "Unknown";
        }
    }

